game.enemy = g.CombatEngine.prepareEnemy({ id: "foresttroll", name: "Troll des forêts", isBoss: false, archetype: "shielded", hp: 100000, maxHp: 100000, stats: g.ENEMY_DB.foresttroll.stats, resists: [], weak: [] });
