  var wkHtml = run("buildWorkshopSheetHTML('moulin')");
  ok(wkHtml.indexOf("confirmCraftWorkshop('moulin')") !== -1, "feuille du Moulin : Fabriquer câblé sur son id (Blé en stock)");
