/* [100] v3.305.0 — W-2 : la carte du Désert et l'étape 4 « Les pierres qui dépassent ». */
console.log("\n[100] v3.305.0 — Carte du Désert, Ensablement, étape 4");
(function () {
  var LM = g.LivingMapManager, MAP = g.LIVING_MAPS.desert, MB = g.MissionBoard;
  game = freshCombat("knight");
  run("StoryQuestManager.ensure(); WarehouseManager.addResource('petite_ration', 5, true);");
  game.unlockedTabs.village = true;
  game.livingMaps = {}; LM._validated = null;
  var steps = g.STORY_QUESTS.desert.steps, i4 = steps.findIndex(function (x) { return x.id === "desert_04"; });
  game.storyQuests.forest.currentStep = g.STORY_QUESTS.forest.steps.length;

  /* Données */
  var rings = {}; MAP.sectors.forEach(function (d) { rings[d.ring] = (rings[d.ring] || 0) + 1; });
  ok(MAP.sectors.length === 12 && rings[1] === 4 && rings[2] === 5 && rings[3] === 3 && MAP.asset === "images/Maps/desert.jpg", "12 secteurs (4/5/3) sur l'image de Seb");
  ok(MAP.sectors.every(function (d) { return d.neighbors.every(function (n) { var o = LM.getSectorDef("desert", n); return o && o.neighbors.indexOf(d.id) !== -1; }); }), "voisinages symétriques");
  ok(MAP.village.name === "Le camp du Portail", "foyer : le camp du Portail");

  /* Carte fermée avant l'étape 4 */
  game.storyQuests.desert.currentStep = i4 - 1;
  ok(LM.getMapForWorld("desert") === null && LM.getMapForWorld("forest") !== null, "étape 3 : pas encore de carte du Désert (la Forêt garde la sienne)");
  var pa = MB._petiteAventureMission("petite_aventure_desert");
  ok(pa && pa.blurb.indexOf(MB._PA_BLURB) === 0, "étape 3 : la Petite Aventure du Désert se lance directement");
  game.storyQuests.desert.currentStep = i4;
  ok(LM.getMapForWorld("desert") === MAP, "étape 4 : la carte s'ouvre");
  pa = MB._petiteAventureMission("petite_aventure_desert");
  ok(/carte du Désert/.test(pa.blurb) && /sable/.test(pa.blurb), "étape 4 : la Petite Aventure passe par la carte du Désert");

  /* Secteurs fermés par l'Histoire */
  ["scarabees", "tour_guet", "bete_dune", "porte_temple"].forEach(function (id) {
    ok(!LM.isReachable("desert", id) && /L'Histoire/.test(LM.canStart("desert", id).reason), id + " : fermé par l'Histoire, le mur le dit");
  });
  ok(LM.getOpenTargets("desert").sort().join() === "caravane,puits_sec,steles", "au départ : le puits sec, la caravane, les stèles");

  /* Départ depuis un secteur */
  game.explorationProgression.petiteAventure = { day: "", count: 0 };
  ok(LM.start("desert", "puits_sec").ok && game.sceneRun.templateId === "petite_aventure_desert" && game.sceneRun.livingMap.sectorId === "puits_sec", "départ du puits sec : une Petite Aventure du Désert ciblée");
  run("SceneRunManager.clearRun();");

  /* Première libération : Verre des dunes */
  var seve0 = g.WarehouseManager.getAmount("seve_aeswyn"), verre0 = g.WarehouseManager.getAmount("verre_des_dunes");
  var rep = LM.onRunEnd("desert", "puits_sec", "success");
  ok(g.WarehouseManager.getAmount("verre_des_dunes") === verre0 + 5 && g.WarehouseManager.getAmount("seve_aeswyn") === seve0 && /Verre des dunes/.test(rep.message), "première libération : +5 Verre des dunes, pas de Sève");
  ok(steps[i4].check(game) === false && /1\/2/.test(steps[i4].progress(game)), "étape 4 : 1/2");

  /* Effets tenus : Outre renforcée, Réservoir plus rapide */
  ok(g.Pa2Run.drinkAmount("outre") === 55, "puits sec tenu : l'Outre rend 55");
  LM.onRunEnd("desert", "steles", "success");
  ok(steps[i4].check(game) === true, "deux secteurs libérés : étape validée");
  LM.onRunEnd("desert", "oasis", "success");
  var rec = g.WORKSHOPS_CONFIG.reservoir.recipes[0];
  ok(g.WorkshopsSystem.getLivingMapSpeedMult("reservoir") === 1.10, "oasis basse tenue : Réservoir 10 % plus rapide");

  /* Ensablement */
  var rand0 = LM._rand; LM._rand = function () { return 0.999; };
  try {
    // v3.366.0 (option A) : la verrerie jamais libérée — rien n'est repris ; puis un rejeu raté du puits sec le reprend, lui
    var f0 = LM.onRunEnd("desert", "verrerie", "fail");
    ok(f0.regressed === null && LM.getState("desert", "puits_sec").state === "libere", "échec devant la verrerie (première tentative) : rien n'est repris");
    var fail = LM.onRunEnd("desert", "puits_sec", "fail");
    ok(fail.regressed === "puits_sec" && /L'Ensablement a repris Le puits sec/.test(fail.message) && /depuis le camp/.test(fail.message) && LM.getState("desert", "puits_sec").state === "recouvert",
      "rejeu raté du puits sec : l'Ensablement le reprend, « reprends-le depuis le camp »");
    ok(g.Pa2Run.drinkAmount("outre") === 40 && g.WorkshopsSystem.getLivingMapSpeedMult("reservoir") === 1.10, "l'Outre perd son bonus, le Réservoir garde le sien");
    LM.onRunEnd("desert", "oasis", "fail"); LM.onRunEnd("desert", "steles", "fail");
    ok(steps[i4].check(game) === true, "l'étape reste acquise même si le sable reprend tout");
  } finally { LM._rand = rand0; }

  /* Mots de la Forêt inchangés */
  var wf = LM.getWords("forest");
  ok(wf.cover === "le Recouvrement" && wf.home === "le village" && LM.getRewardResourceId("forest") === "seve_aeswyn", "la Forêt garde la brume, le Recouvrement et la Sève");
  ok(/Ensablé/.test(g.buildLivingMapLegendHTML ? (function () { var o = g.livingMapOpenId; g.livingMapOpenId = "desert"; var h = run("livingMapOpenId = 'desert'; var __h = buildLivingMapLegendHTML(); livingMapOpenId = null; __h"); return h; })() : ""), "légende du Désert : « Ensablé »");
})();

/* [101] v3.306.0 — W-2 : l'étape 5 « Les noms sous le sable », premier choix pesant. */
console.log("\n[101] v3.306.0 — Les noms sous le sable : choix, registre, stèles");
(function () {
  var LM = g.LivingMapManager, SQ = g.StoryQuestManager;
  var steps = g.STORY_QUESTS.desert.steps, i5 = steps.findIndex(function (x) { return x.id === "desert_05"; }), st5 = steps[i5];
  function fresh() {
    game = freshCombat("knight");
    run("StoryQuestManager.ensure();");
    game.unlockedTabs.village = true;
    game.livingMaps = {}; LM._validated = null;
    game.storyQuests.forest.currentStep = g.STORY_QUESTS.forest.steps.length;
    game.storyQuests.desert.currentStep = i5;
    game.storyQuests.desert.accepted = true;
  }
  fresh();
  ok(i5 === 4 && st5.choice && st5.choice.options.length === 2 && st5.tutorial && st5.tutorial.title === "Un choix qui pèse", "5e étape du Désert : un choix à deux options, tutoriel « Un choix qui pèse »");
  ok(st5.linkTo.cardId === "livingmap_desert:steles", "le lien ouvre la carte sur les stèles");

  /* Les stèles d'abord */
  ok(g.storyPendingChoiceAt("desert", "steles") === null && /Stèles libérées 0\/1 · Choix 0\/1/.test(st5.progress(game)), "stèles pas libérées : pas de choix, l'étape le dit");
  LM.onRunEnd("desert", "steles", "success");
  game.storyQuests.desert.accepted = false;
  ok(g.storyPendingChoiceAt("desert", "steles") === null, "étape non acceptée : pas de choix");
  game.storyQuests.desert.accepted = true;
  var pend = g.storyPendingChoiceAt("desert", "steles");
  ok(pend && pend.chapterId === "desert" && g.storyPendingChoiceAt("desert", "puits_sec") === null, "stèles libérées, étape acceptée : le choix se pose là, et seulement là");
  run("livingMapOpenId = 'desert'; livingMapSelected = 'steles';");
  ok(run("buildLivingMapPanelHTML('desert', null)").indexOf("openStoryChoiceModal('desert')") !== -1, "le volet des stèles propose « Lire les noms »");
  var modal = run("buildStoryChoiceModalHTML('desert')");
  ok(/Déterrer les noms/.test(modal) && /Le sable reprend les stèles/.test(modal) && /Les laisser au sable/.test(modal) && /tiennent le sable/.test(modal) && !/jauge|%/.test(modal), "écran : deux options, conséquences en clair, aucune jauge");

  /* Déterrer */
  var ess0 = Number(game.gold || 0); /* v3.358.0 : l'essence des noms devient de l'or */
  ok(g.storyMakeChoice("desert", "deterrer") === true, "déterrer : choix accepté");
  ok(SQ.getChoice("noms") === "deterrer" && SQ.getRegister().donner === 1 && SQ.getRegister().garder === 0, "registre : Donner");
  ok(Number(game.gold) === ess0 + g.STORY_NOMS_GOLD && LM.getState("desert", "steles").state === "recouvert", "or tout de suite, les stèles retournent au sable");
  ok(g.storyMakeChoice("desert", "laisser") === false && SQ.getChoice("noms") === "deterrer", "définitif : un second choix ne change rien");
  ok(st5.check(game) === true && /déjà les stèles/.test(st5.narrative.completion), "étape validée, complétion « Déterrer »");
  LM.onRunEnd("desert", "steles", "success");
  ok(LM.isLiberated("desert", "steles") && !LM.hasEffect("autel_normale") && /La stèle est vide/.test(run("buildLivingMapPanelHTML('desert', null)")), "reprises, les stèles n'ont plus d'effet : la stèle est vide");
  ok(LM.getBrakeChance("desert") === LM.getBrakeChance(), "déterrer : aucun frein en plus");

  /* Laisser */
  fresh();
  LM.onRunEnd("desert", "steles", "success");
  ok(g.storyMakeChoice("desert", "laisser") === true && SQ.getRegister().garder === 1, "laisser : registre Garder");
  ok(LM.isLiberated("desert", "steles") && LM.hasEffect("autel_normale"), "les stèles restent libérées, leur effet aussi");
  ok(Math.abs(LM.getBrakeChance("desert") - (LM.getBrakeChance() + 0.10)) < 1e-9 && LM.getBrakeChance("forest") === LM.getBrakeChance(), "elles tiennent le sable : +10 % de frein au Désert, rien en Forêt");
  LM.regress("desert", "steles", "test");
  ok(LM.getBrakeChance("desert") === LM.getBrakeChance(), "stèles ensablées : le frein retombe");
  ok(/sans la peser/.test(st5.narrative.completion), "complétion « Laisser »");
  run("livingMapOpenId = null; livingMapSelected = null;");
})();

/* [102] v3.306.1 — Carte : image pré-calculée (latence au glissé sur iPhone). */
console.log("\n[102] v3.306.1 — Carte : brume et Recouvrement pré-calculés, gestes allégés");
(function () {
  var LM = g.LivingMapManager;
  game = freshCombat("knight");
  run("StoryQuestManager.ensure();");
  game.unlockedTabs.village = true; game.livingMaps = {}; LM._validated = null;
  LM.onRunEnd("forest", "gue", "success"); LM.onRunEnd("forest", "menhirs", "success"); LM.regress("forest", "menhirs", "t");
  run("LIVING_MAP_BAKE.key = null; LIVING_MAP_BAKE.url = null; LIVING_MAP_BAKE.pending = null;");
  var html = run("buildLivingMapHTML('forest')");
  ok(/lm-fog is-on/.test(html) && /lm-cover is-on/.test(html) && !/lm-cover-trame/.test(html), "sans canvas (ou avant le calcul) : les calques CSS d'origine restent");
  var k1 = run("livingMapBakeKey(LIVING_MAP_TMP = LivingMapManager.getMap('forest'), ['arbremere'], ['menhirs'])");
  var k2 = run("livingMapBakeKey(LIVING_MAP_TMP, ['arbremere'], [])");
  ok(k1 !== k2, "l'image est recalculée dès que l'état de la carte change");
  run("LIVING_MAP_BAKE.key = " + JSON.stringify(run("livingMapBakeKey(LivingMapManager.getMap('forest'), " + JSON.stringify(LM.getMap("forest").sectors.filter(function (d) { return LM.getState("forest", d.id).state === "voile"; }).map(function (d) { return d.id; })) + ", ['menhirs'])")) + "; LIVING_MAP_BAKE.url = 'blob:test';");
  html = run("buildLivingMapHTML('forest')");
  ok(/url\('blob:test'\)/.test(html) && !/lm-fog is-on/.test(html) && !/lm-cover is-on/.test(html) && /lm-cover-trame/.test(html), "image prête : un seul calque d'image, la trame du Recouvrement en CSS");
  var gray = run("lmFilterPixel([['grayscale', 1]], [1, 0, 0])");
  ok(Math.abs(gray[0] - 0.2126) < 1e-9 && Math.abs(gray[1] - 0.2126) < 1e-9, "filtres : matrices de la spec (grayscale(1) du rouge = 0,2126)");
  var br = run("lmFilterPixel([['brightness', 1.35]], [0.9, 0.5, 0])");
  ok(br[0] === 1 && Math.abs(br[1] - 0.675) < 1e-9, "filtres : bornés à chaque étape, comme le navigateur");
  run("LIVING_MAP_BAKE.key = null; LIVING_MAP_BAKE.url = null;");
})();

/* [104] v3.307.0 — Héros en expédition : rien de ce qui le touche ne se fait ailleurs. */
console.log("\n[104] v3.307.0 — verrou héros pendant une expédition (Chemin long, retour Seb)");
(function () {
  var game = freshCombat("knight"); giveWeapon();
  if (g.SortieManager.isActive()) g.SortieManager.end("return");
  game.activeTab = "village"; game.dungeonRunsUsed = {}; game.gold = 1e7; game.resources.ration = 3;
  game.potionsOwned.potion_power = 2;
  g.SceneRunManager.startRun("bosquet_silencieux"); // v3.391.0 : parcours v2
  ok(g.SceneRunManager.isHeroEngaged() === true && !!g.heroLockReason(), "expédition sur la carte : héros engagé");

  g.DungeonManager.start(1);
  ok(game.dungeonRun.active !== true && Object.keys(game.dungeonRunsUsed || {}).length === 0, "donjon refusé, aucune sortie décomptée");
  g.AdventureQuestManager.start("hq_wolf_pack");
  ok(game.adventureQuestRun.active !== true, "quête d'aventure refusée");
  g.HuntQuestManager.start("hq_forest_battue");
  ok(game.huntRun.active !== true, "chasse refusée");
  ok(game.sortie.active === true && game.sortie.context === "scene", "la sortie de l'expédition est intacte");
  ok(g.SortieManager.end("return") === null && game.sortie.active === true, "filet : end('return') ne clôt pas une expédition en cours");
  var lm = g.LivingMapManager.startEliteFight("forest", "x", { eliteId: Object.keys(g.ELITE_DB)[0] });
  ok(lm.ok === false && !game.livingMaps.fight, "élite de carte refusée");

  game.heroHp = 10;
  ok(g.CampManager.canEatRation("ration") === false && g.CampManager.eatRation("ration") === false && game.resources.ration === 3 && game.heroHp === 10, "rations gelées");
  ok(g.CampManager.isRegenActive() === false, "pas de régénération au camp");
  g.PotionManager.usePotion("potion_power");
  ok(g.PotionManager.isArmed("potion_power") === false && g.PotionManager.getStock("potion_power") === 2, "potion non armée");

  game.inventory.push({ uid: "t_eq", name: "Anneau", rarity: "common", slot: "ring", stat: "tapDmg", value: 5 });
  g.EquipmentManager.equip("t_eq");
  ok(!game.equipped.ring, "équipement : pas de changement");
  g.EquipmentManager.unequip("weapon");
  ok(!!game.equipped.weapon, "équipement : pas de retrait");
  var lvl0 = game.upgrades.utrain_power || 0;
  g.buyUpgrade("utrain_power", 5);
  ok((game.upgrades.utrain_power || 0) === lvl0, "entraînement refusé");
  ok(g.isGrimoireEditable() === false, "Grimoire en lecture seule");
  ok(g.ForgeManager.getBlockReason("weapon") === "Forge non construite" || g.ForgeManager.getBlockReason("weapon") === "Héros en expédition", "Forge : refus (bâtiment absent ou héros engagé)");
  ok(g.EnchantManager._isEquipped(game.equipped.weapon) === true && g.EnchantManager._isEquipped(game.inventory[game.inventory.length - 1]) === false, "Enchanteresse : seule la pièce portée est gelée");

  g.SceneRunManager.abandon();
  ok(g.SceneRunManager.isHeroEngaged() === false && g.heroLockReason() === null, "expédition terminée : verrou levé");
  ok(g.CampManager.eatRation("ration") === true, "rations de nouveau disponibles");
  g.EquipmentManager.equip("t_eq");
  ok(game.equipped.ring && game.equipped.ring.uid === "t_eq", "équipement de nouveau libre");
})();

/* [105] v3.308.0 — vitrine plafonnée à 25 % de la rareté du sommet ; entraînements à 150. */
console.log("\n[105] v3.308.0 — boutique (25 % de rareté du sommet) et plafond commun des entraînements");
(function () {
  run("fullResetState(); game.playerName='Test'; game.heroId='knight'; EquipmentManager.recalcStats();");
  var ids = ["utrain_power", "utrain_endurance", "utrain_celerity", "utrain_precision", "utrain_will"];
  ok(ids.every(function (id) { return g.UPGRADES.filter(function (u) { return u.id === id; })[0].maxLevel === 150; }), "les cinq entraînements plafonnent à 150");
  ok(g.EquipShopManager.getTopRarityCap(6) === 1 && g.EquipShopManager.getTopRarityCap(8) === 2 && g.EquipShopManager.getTopRarityCap(11) === 2 && g.EquipShopManager.getTopRarityCap(3) === 1, "plafond : 1 sur 6, 2 sur 8 à 11, minimum 1");
  game = g.game; game.equipShopStarterServed = true;
  var saveW = g.WorldManager.worldIndex;
  g.WorldManager.worldIndex = 1;
  var worst = 0, greens = 0, total = 0, prices = true;
  for (var i = 0; i < 400; i++) {
    var st = g.EquipShopManager.generateStock();
    var n = st.filter(function (it) { return it.rarity === "green"; }).length;
    worst = Math.max(worst, n); greens += n; total += st.length;
    if (st.some(function (it) { return typeof it.price !== "number" || it.bought !== false; })) prices = false;
  }
  ok(worst <= 1, "Désert, vitrine de 6 : jamais plus d'1 Inhabituel sur 400 vitrines (max " + worst + ")");
  ok(greens > 200, "l'Inhabituel reste présent (" + greens + " sur 400 vitrines)");
  ok(prices && total === 2400, "prix posés après la borne, 6 objets par vitrine");
  g.WorldManager.worldIndex = 0;
  var st0 = g.EquipShopManager.generateStock();
  ok(st0.every(function (it) { return it.rarity === "common"; }), "Forêt : une seule rareté, aucun effet");
  g.WorldManager.worldIndex = saveW;
})();

/* [106] v3.310.0 — W-3a : acte II, étapes 6 « La descente » et 7 « Un homme assis ». */
console.log("\n[106] v3.310.0 — W-3a : la descente au Temple, le Veilleur");
(function () {
  var LM = g.LivingMapManager, SQ = g.StoryQuestManager, R = g.SceneRunManager, WT = g.WorldTravel;
  var steps = g.STORY_QUESTS.desert.steps;
  var i6 = steps.findIndex(function (x) { return x.id === "desert_06"; }), st6 = steps[i6], st7 = steps[i6 + 1];
  game = freshCombat("knight"); giveWeapon();
  run("StoryQuestManager.ensure(); CompanionManager.unlock('wenna');");
  game.unlockedTabs.village = true;
  game.livingMaps = {}; LM._validated = null;
  game.storyQuests.forest.currentStep = g.STORY_QUESTS.forest.steps.length;
  WT.arrive("desert", 0);
  game.storyQuests.desert.currentStep = i6; game.storyQuests.desert.accepted = true;
  ok(i6 === 5 && st7 && st7.id === "desert_07" && steps.length >= 7, "acte II : desert_06 puis desert_07");
  ok(st6.narrative.dialogue.length === 4 && st6.narrative.completionDialogue.length === 3 && st6.linkTo.cardId === "livingmap_desert:porte_temple", "étape 6 : textes validés, lien vers la porte du Temple");

  /* La porte : par l'anneau 2 seulement */
  var cs = LM.canStart("desert", "porte_temple");
  ok(cs.ok === false && /Libère d'abord/.test(cs.reason), "porte fermée tant que ni la verrerie ni le marché de sel ne sont libérés");
  LM.onRunEnd("desert", "verrerie", "success");
  cs = LM.canStart("desert", "porte_temple");
  ok(cs.ok === true && cs.content.templateId === "descente_temple", "verrerie libérée : la porte s'ouvre sur la descente");
  var saveCap = R.canStartPetiteAventureToday;
  R.canStartPetiteAventureToday = function () { return false; };
  ok(LM.canStart("desert", "porte_temple").ok === true && LM.canStart("desert", "marche_sel").ok === false, "cap du jour épuisé : la descente reste ouverte, une Petite Aventure non");
  R.canStartPetiteAventureToday = saveCap;

  /* Le run */
  var rat0 = g.WarehouseManager.getAmount("ration");
  /* v3.390.0 (chantier P, P-2) : parcours v2 (carte du Temple depuis v3.392.0). Héros au niveau de l'étape 6 (repère de campagne : 9). */
  game.heroLevel = 9; game.equipped.weapon.value = 600; run("EquipmentManager.recalcStats();"); game.heroHp = game.heroMaxHp;
  ok(LM.start("desert", "porte_temple").ok === true && game.sceneRun.templateId === "descente_temple" && game.sceneRun.parcours && game.sceneRun.status === "pa2-map", "départ depuis la carte, sans préparation");
  ok(g.WarehouseManager.getAmount("ration") === rat0 && game.sceneRun.map.image === g.PA2_PARCOURS_IMAGES.desert_temple.image, "aucun coût d'entrée ; carte du Temple");
  var r = game.sceneRun, types = ["P0", "P1", "P2", "P3"].map(function (k) { var n = r.nodes[k]; return n.type + (n.gabaritId ? "/" + n.gabaritId : "") + (n.foeId ? "/" + n.foeId + "x" + n.pack : ""); }).join(" ");
  ok(types === "obstacle/dalle_scellee obstacle/dalles_ensablees combat/sandwarriorx1 source", "parcours scripté : " + types);
  ok(/Le battant ouvert/.test(r.nodes.P0.narr) && /La lumière de la porte est petite/.test(r.nodes.P2.after), "journal : texte à chaque étape, et après le guerrier");
  playParcours(true);
  ok(r.end && r.end.how === "parcours" && g.WorldManager.worldIndex === 1 && g.WorldManager.adventureIndex === 1, "arrivée : le Temple ensablé");
  ok(LM.isLiberated("desert", "porte_temple") && LM.getContentFor("desert", "porte_temple").templateId === "petite_aventure_desert", "porte libérée ; elle redevient une Petite Aventure");
  ok(st6.check(game) === true && WT.defaultAdventureFor("desert") === 1, "étape 6 prête ; un voyage retour ramène au Temple");

  run("window.__openQC = openQuestCompletePopup; window.openQuestCompletePopup = function (c) { window.__qc = c; };");
  SQ.claimStep("desert");
  var popup = g.__qc;
  run("window.openQuestCompletePopup = window.__openQC;");
  ok(popup && popup.dialogue && popup.dialogue.length === 3 && popup.text.indexOf("Personne sur la chaise") !== -1, "réclamation : la chaise vide");
  ok(SQ.getCurrentStep("desert").id === "desert_07", "l'étape 7 s'ouvre");

  /* Étape 7 : l'Outre */
  SQ.acceptStep("desert");
  ok(st7.narrative.dialogue.length === 5 && st7.narrative.dialogue[0].who === "Le Veilleur" && st7.narrative.completionDialogue.length === 4, "étape 7 : le Veilleur, textes validés");
  ok(SQ.getOfferingInfo(null, "camp") === null, "l'Outre ne se donne pas au feu de camp");
  var info = SQ.getOfferingInfo("desert", "story");
  ok(info && info.canOffer === false && st7.check(game) === false, "sans Outre : pas encore");
  var html = g.buildStoryCurrentStepHTML("desert", g.STORY_QUESTS.desert, st7, i6 + 1);
  ok(/ disabled>Donner l&#39;Outre/.test(html) && /Le Réservoir la remplit/.test(html) && /Aller au Réservoir/.test(html), "carte d'étape : bouton grisé, raison, lien vers le Réservoir");
  run("WarehouseManager.addResource('outre_pleine', 1, true);");
  html = g.buildStoryCurrentStepHTML("desert", g.STORY_QUESTS.desert, st7, i6 + 1);
  ok(/offerToEmbers\('desert'\)">Donner l&#39;Outre/.test(html) && !/Aller au Réservoir/.test(html), "avec l'Outre : bouton actif");
  ok(SQ.offerToEmbers("desert") === true && g.WarehouseManager.getAmount("outre_pleine") === 0, "l'Outre est donnée");
  ok(st7.check(game) === true && SQ.isCurrentStepReady("desert") === true && game.storyQuests.forest.counters.offeringDone !== 1, "étape 7 prête ; le compteur des braises de la Forêt n'est pas touché");
})();

/* [107] v3.311.0 — W-3b/W-3c : Maddoc et ses voies, étapes 8 à 10, rencontres scriptées, Tailleur de pierre. */
console.log("\n[107] v3.311.0 — Maddoc, voies, étapes 8 à 10");
(function () {
  var CM = g.CompanionManager, SQ = g.StoryQuestManager, AQ = g.AdventureQuestManager;
  var steps = g.STORY_QUESTS.desert.steps;
  var i8 = steps.findIndex(function (x) { return x.id === "desert_08"; });
  function fresh(met) {
    game = freshCombat("knight"); giveWeapon();
    run("StoryQuestManager.ensure(); CompanionManager.unlock('wenna');");
    game.unlockedTabs.village = true;
    game.storyQuests.forest.currentStep = g.STORY_QUESTS.forest.steps.length;
    g.WorldTravel.arrive("desert", 1);
    game.explorationProgression.maddocMet = met || null; game.explorationProgression.maddocGift = false;
    game.storyQuests.desert.currentStep = i8; game.storyQuests.desert.accepted = false;
  }
  // v3.314.0 : la longueur du chapitre n'est plus figée — l'acte III ajoute ses étapes à la suite.
  ok(i8 === 7 && steps[8].id === "desert_09" && steps[9].id === "desert_10" && /Acte II/.test(steps[9].act), "acte II complet : étapes 6 à 10");

  /* --- Fiche à voies --- */
  var dT = g.getCompanionDef("maddoc", "tronc"), dA = g.getCompanionDef("maddoc", "affut");
  ok(dT.role === "guard" && dA.role === "assault" && dT.skill.type === "taunt" && dA.skill.type === "strike", "deux voies : Garde (Planté) et Assaut (Tir ajusté)");
  ok(g.getCompanionDef("maddoc", "tronc") === dT && dT.upgrades === dA.upgrades && dT.lines.join === dA.lines.join, "fiche fusionnée stable, partie commune partagée");
  ok(g.getVoieChangeCost(0) === 2000 && g.getVoieChangeCost(1) === 6000 && g.getVoieChangeCost(2) === 18000, "changement de voie : 2 000 or, ×3");

  /* --- Étape 8 : arrivée, cadeau, choix --- */
  fresh(null);
  SQ.acceptStep("desert");
  var st = CM.state("maddoc");
  ok(st.unlocked && st.present && st.voie === null && st.upgrades === 0, "acceptation : Maddoc rejoint, présent, voie à choisir, aucune amélioration");
  ok(CM.partyIds().join(",") === "wenna,maddoc", "trio : Wenna et Maddoc");
  ok(steps[i8].narrative.dialogue[2].text === g.STORY_MADDOC_GREETING.none, "jamais croisé : « J'habite de l'autre côté »");
  fresh("aided");
  SQ.acceptStep("desert");
  ok(CM.state("maddoc").upgrades === 1 && game.explorationProgression.maddocGift === true && steps[i8].narrative.dialogue[2].text === g.STORY_MADDOC_GREETING.aided, "aidé en surface : première amélioration offerte, « La gourde »");
  steps[i8].onAccept();
  ok(CM.state("maddoc").upgrades === 1, "le cadeau n'est donné qu'une fois");
  fresh("passed");
  SQ.acceptStep("desert");
  ok(CM.state("maddoc").upgrades === 0 && /pressé/.test(steps[i8].narrative.dialogue[2].text), "passé : pas de cadeau, « Tu étais pressé »");

  var pend = g.storyPendingCardChoice("desert");
  ok(pend && pend.choice.key === "maddocVoie", "choix de voie en attente sur la carte d'étape");
  var html = g.buildStoryCurrentStepHTML("desert", g.STORY_QUESTS.desert, steps[i8], i8);
  ok(/Choisir sa voie/.test(html), "la carte d'étape propose « Choisir sa voie »");
  AQ.start("aq_desert_gouffre");
  ok(game.adventureQuestRun.active !== true, "pas de départ sans voie");
  var reg0 = JSON.stringify(SQ.getRegister());
  ok(g.storyMakeChoice("desert", "affut") === true && CM.state("maddoc").voie === "affut", "voie choisie : l'affût");
  ok(SQ.getChoice("maddocVoie") === null && JSON.stringify(SQ.getRegister()) === reg0 && g.storyPendingCardChoice("desert") === null, "hors registre, plus de choix en attente");
  ok(g.storyMakeChoice("desert", "tronc") === false && CM.state("maddoc").voie === "affut", "le premier choix ne se refait pas par l'Histoire");

  /* --- Les trois rencontres --- */
  AQ.start("aq_desert_gouffre");
  ok(game.adventureQuestRun.active === true, "départ avec la voie choisie");
  var ids = [];
  for (var k = 0; k < 3; k++) {
    var foes = game.combat && game.combat.enemies ? game.combat.enemies.slice() : [game.enemy];
    ids.push(foes.map(function (e) { return e.id; }).join("+"));
    foes.forEach(function (e) { e.hp = 0; g.CombatEngine.killEnemy(e); });
  }
  ok(ids.join(" ") === "sandwarrior sandworm scorpion", "rencontres dans l'ordre : " + ids.join(" "));
  ok(game.adventureQuestsCompleted.aq_desert_gouffre === true && steps[i8].check(game) === true, "trois rencontres : étape 8 prête");

  /* --- Voies en combat --- */
  game = freshCombat("knight"); giveWeapon();
  run("CompanionManager.unlock('wenna'); CompanionManager.unlock('maddoc');");
  CM.chooseVoie("maddoc", "tronc");
  CM.onCombatStart();
  var allies = g.CombatActors.aliveAllies(), md = allies.filter(function (a) { return a.companionId === "maddoc"; })[0];
  ok(md && md.role === "guard" && md.threatMult === 1.8, "acteur du tronc : Garde, menace ×1,8");
  md.hp = Math.floor(md.maxHp / 2);
  var hp0 = md.hp;
  ok(CM.useSkill(md, g.getCompanionDef("maddoc")) === true && md.hp > hp0 && md.cooldown === 4, "Planté : il se soigne, recharge 4");
  var hits = 0;
  for (var n = 0; n < 300; n++) { if (g.CombatEngine.pickVictim() === md) hits++; }
  ok(hits > 180, "Planté : il attire les coups (" + hits + "/300)");
  md.cooldown = 0; md.threat = 0;
  var sansBlesse = CM.chooseAction(md);
  ok(sansBlesse === "basic", "politique : pas de Planté si personne d'autre n'est touché");
  game.heroHp = Math.floor(game.heroMaxHp * 0.5);
  ok(CM.chooseAction(md) === "skill", "politique : Planté dès qu'un allié est touché");

  game = freshCombat("knight"); giveWeapon();
  run("CompanionManager.unlock('maddoc');");
  CM.chooseVoie("maddoc", "affut");
  CM.onCombatStart();
  md = g.CombatActors.aliveAllies().filter(function (a) { return a.companionId === "maddoc"; })[0];
  var cible = g.CombatActors.target(); cible.hp = cible.maxHp = 1e6;
  ok(CM.useSkill(md, g.getCompanionDef("maddoc")) === true && cible.hp <= 1e6 - Math.floor(md.damage * 2.5) + 1 && md.cooldown === 3, "Tir ajusté : ×2,5 ses dégâts, recharge 3");

  /* --- Changement de voie, sauvegarde --- */
  game.gold = 1999;
  ok(CM.changeVoie("maddoc", "tronc") === false && CM.state("maddoc").voie === "affut", "pas assez d'or : refusé");
  CM.state("maddoc").upgrades = 2; game.gold = 2000;
  ok(CM.changeVoie("maddoc", "tronc") === true && game.gold === 0 && CM.state("maddoc").voieChanges === 1 && CM.state("maddoc").upgrades === 2, "changement payé, améliorations conservées");
  var data = JSON.parse(JSON.stringify(CM.buildSaveData()));
  CM.restore(data);
  ok(CM.state("maddoc").voie === "tronc" && CM.state("maddoc").voieChanges === 1, "voie et compteur de changements survivent au rechargement");
  var card = g.buildCompanionCardHTML("maddoc"), cardW = (CM.unlock("wenna"), g.buildCompanionCardHTML("wenna"));
  ok(/cp-voie/.test(card) && card.indexOf("Changer : " + g.formatNumber(6000) + " or") !== -1 && !/healThreshold/.test(card) && /healThreshold/.test(cardW), "fiche : bloc Voie et prix suivant pour Maddoc, réglages de soin pour Wenna seulement");

  /* --- Étape 10 : un groupe = une rencontre --- */
  game = freshCombat("knight"); giveWeapon();
  run("AdventureQuestManager.ensureDefaults();");
  AQ.start("aq_desert_nuee");
  var nuee = game.combat.enemies.slice();
  ok(nuee.length === 3 && nuee.every(function (e) { return e.id === "scarab"; }), "rencontre 1 : une nuée de trois");
  nuee[0].hp = 0; g.CombatEngine.killEnemy(nuee[0]);
  ok(game.adventureQuestProgress.aq_desert_nuee.rencontres_nuee === 0, "un scarabée abattu : la rencontre n'est pas finie");
  nuee.slice(1).forEach(function (e) { e.hp = 0; g.CombatEngine.killEnemy(e); });
  ok(game.adventureQuestProgress.aq_desert_nuee.rencontres_nuee === 1, "nuée entière : un cran");
  var paire = game.combat.enemies.slice();
  ok(paire.length === 2 && paire.every(function (e) { return e.id === "sandwarrior"; }), "rencontre 2 : une paire de guerriers");
  AQ.forfeit();

  /* --- Étape 9 : le Tailleur de pierre --- */
  fresh(null);
  var W = g.WORKSHOPS_CONFIG.tailleur_de_pierre;
  ok(W.active === false, "Tailleur fermé avant l'étape 9");
  game.storyQuests.desert.currentStep = i8 + 1;
  ok(W.active === true && W.recipes[0].outputs[0].resourceId === "verre_trempe" && !!g.WAREHOUSE_RESOURCES.verre_trempe, "étape 9 : le Tailleur s'ouvre, recette du Verre trempé");
  run("ProductionManager.unlockBuilding && ProductionManager.unlockBuilding('quarry'); WarehouseManager.addResource('verre_des_dunes', 4, true); WarehouseManager.addResource('pierre', 20, true);");
  ok(g.WorkshopsSystem.enqueueCraft("tailleur_de_pierre", "verre_trempe", 1) === true, "un Verre trempé mis en fabrication");
  g.WorkshopsSystem.tickWorkshop("tailleur_de_pierre", 40000);
  ok(g.WarehouseManager.getAmount("verre_trempe") >= 1 && steps[i8 + 1].check(game) === true, "premier lot : étape 9 prête");
  ok(g.WorkshopsSystem.LIVING_MAP_EFFECT_BY_WORKSHOP.tailleur_de_pierre === "tailleur_plus", "l'effet de la verrerie vise bien l'atelier");
  ok(g.LivingMapManager.canStart("desert", "scarabees").reason !== "Pas encore. L'Histoire t'y mènera plus tard." || game.storyQuests.desert.currentStep < i8 + 2, "champ de scarabées fermé avant l'étape 10");
})();

/* [108] v3.312.0 — W-3d : événements à branches en Petite Aventure, Maddoc en surface. */
console.log("\n[109] v3.313.0 — Boutique : Bourse et Contrats retirés, remboursement");
(function () {
  game = freshCombat("knight");
  ok(!g.UPGRADES.some(function (u) { return u.id === "u_gold" || u.id === "u_bounty"; }) && g.UPGRADES.length === 5, "il ne reste que les cinq entraînements");
  game.gold = 0; game.upgrades.u_gold = 3; game.upgrades.u_bounty = 1;
  var attendu = 55 + 60 + 66 + 260; // floor(55·1,1^l) pour l = 0..2, puis 260
  var logs = []; var addLog0 = g.addLog; g.addLog = function (t) { logs.push(t); };
  try { g.ensureGameStateDefaults(); } finally { g.addLog = addLog0; }
  ok(game.gold === attendu, "or rendu : " + game.gold + " (attendu " + attendu + ")");
  ok(game.upgrades.u_gold === undefined && game.upgrades.u_bounty === undefined, "les clés quittent la sauvegarde");
  ok(logs.some(function (t) { return /Bourse lourde ni Contrats lucratifs/.test(t) && /441 or/.test(t); }), "une ligne au journal");
  g.ensureGameStateDefaults();
  ok(game.gold === attendu, "remboursé une seule fois");
  game.upgrades.u_gold = 0; g.ensureGameStateDefaults();
  ok(game.gold === attendu && game.upgrades.u_gold === undefined, "niveau 0 : rien à rendre, clé retirée");
  g.setShopSubTab("upgrades");
  var html = g.buildShopHTML();
  ok(!/Économie/.test(html) && !/Bourse lourde/.test(html) && !/pc-subtab-bar/.test(html) && /Potions/.test(html), "Boutique : Potions seules, plus d'onglet Économie");
  var f4 = g.STORY_QUESTS.forest.steps[3];
  game.potionsOwned = {}; game.healingPotionsOwned = {};
  ok(!f4.check(game), "étape Boutique de la Forêt : pas validée sans achat");
  game.healingPotionsOwned = { potion_soin_mineur: 1 };
  ok(f4.check(game), "une potion suffit");
})();

/* [110] v3.314.0 (W-4a1) — Étape 11 « Le serment sous l'armure » : élite de la tour de guet,
   choix pesant, heaume du guet, frein et effet perdu. */
console.log("\n[110] v3.314.0 — Acte III, étape 11 : le Serment sous l'armure");
(function () {
  game = freshCombat("knight");
  var e = g.ELITE_DB.serment_armure;
  ok(!!e && e.baseId === "sandwarrior" && e.archetype === "armored", "l'élite existe, base Guerrier des sables, Blindée");
  ok(!e.repeatable, "première libération seulement : l'élite n'est pas répétable");
  var sect = g.LIVING_MAPS.desert.sectors.filter(function (d) { return d.id === "tour_guet"; })[0];
  ok(sect && sect.requiresStoryStep === "desert_11" && sect.content.eliteId === "serment_armure", "la tour attend l'étape 11 et porte l'élite");
  ok(!!sect.effectLostOnChoice && sect.effectLostOnChoice.key === "serment" && sect.effectLostOnChoice.value === "relever", "relever fait perdre l'effet de la tour");
  var cb = g.LIVING_MAPS.desert.choiceBrakes.filter(function (c) { return c.key === "serment"; })[0];
  ok(!!cb && cb.value === "laisser" && cb.sectorId === "tour_guet", "laisser pose un frein sur la tour");

  var step = g.STORY_QUESTS.desert.steps.filter(function (st) { return st.id === "desert_11"; })[0];
  ok(!!step && step.choice.key === "serment" && step.choice.sectorId === "tour_guet", "l'étape 11 porte le choix sur la tour");
  ok(!step.check(), "sans choix, l'étape n'est pas validée");

  // Le chapitre du Désert ne s'ouvre qu'une fois la Forêt finie et le monde atteint
  // (isChapterOpen) : même amorce que la section [104] de l'acte II.
  var idx = g.STORY_QUESTS.desert.steps.map(function (st) { return st.id; }).indexOf("desert_11");
  function poserEtape11() {
    run("StoryQuestManager.ensure();");
    game.unlockedTabs.village = true;
    game.storyQuests.forest.currentStep = g.STORY_QUESTS.forest.steps.length;
    g.WorldTravel.arrive("desert", 1);
    var c = game.storyQuests.desert;
    c.currentStep = idx; c.accepted = true; c.choices = {};
    g.LivingMapManager.ensureDefaults();
  }
  // Le choix ne s'offre que le secteur libéré (storyPendingChoiceAt).
  poserEtape11();
  ok(!g.storyPendingChoiceAt("desert", "tour_guet"), "tour non libérée : pas de choix proposé");
  g.LivingMapManager.setState("desert", "tour_guet", "libere", "harnais");
  ok(!!g.storyPendingChoiceAt("desert", "tour_guet"), "tour libérée : le choix se propose");

  // Relever : le heaume tombe dans l'inventaire, l'effet de la tour est perdu, le frein ne bouge pas.
  var brake0 = g.LivingMapManager.getBrakeChance("desert");
  var n0 = (game.inventory || []).length;
  g.storyMakeChoice("desert", "relever");
  var heaume = (game.inventory || []).filter(function (it) { return it.eliteId === "heaume_guet"; })[0];
  ok((game.inventory || []).length === n0 + 1 && !!heaume, "relever donne le heaume du guet");
  ok(heaume.slot === "helmet" && heaume.rarity === "green" && heaume.stat === "critMult", "heaume : casque Inhabituel, critMult");
  ok(g.LivingMapManager.isEffectLostByChoice(sect), "l'effet de la tour est perdu");
  ok(Math.abs(g.LivingMapManager.getBrakeChance("desert") - brake0) < 1e-9, "relever n'ajoute aucun frein");
  ok(step.check(), "le choix valide l'étape");

  // Laisser : pas de heaume, effet gardé, frein en plus.
  game = freshCombat("knight");
  poserEtape11();
  g.LivingMapManager.setState("desert", "tour_guet", "libere", "harnais");
  var brakeAvant = g.LivingMapManager.getBrakeChance("desert");
  var m0 = (game.inventory || []).length;
  g.storyMakeChoice("desert", "laisser");
  ok((game.inventory || []).length === m0, "laisser ne donne aucun objet");
  ok(!g.LivingMapManager.isEffectLostByChoice(sect), "l'effet de la tour est gardé");
  ok(g.LivingMapManager.getBrakeChance("desert") > brakeAvant + 0.09, "laisser ajoute le frein de la tour");
})();

/* [111] v3.315.0 (W-4a2) — Étape 12 « La cité engloutie » : verrou d'Histoire du donjon,
   ticket offert piloté par la donnée, relevé de la vague 5. */
console.log("\n[111] v3.315.0 — Acte III, étape 12 : la Cité engloutie");
(function () {
  var cite = g.DUNGEONS.filter(function (d) { return d.id === 2; })[0];
  var taniere = g.DUNGEONS.filter(function (d) { return d.id === 1; })[0];
  ok(!!cite && cite.locked === false && cite.requiresStoryStep === "desert_12", "la Cité n'est plus verrouillée en dur, mais par l'étape 12");
  ok(!!cite.enemyPool && cite.enemyPool.length === 4 && cite.eliteWaves && cite.eliteWaves[5] === "serment_armure", "pool du Désert et vague élite 5");
  ok(!!taniere.storyFreeSteps && taniere.storyFreeSteps.join(",") === "forest_13,forest_14", "la Tanière garde ses deux étapes, désormais en donnée");

  var idx11 = g.STORY_QUESTS.desert.steps.map(function (st) { return st.id; }).indexOf("desert_11");
  var idx12 = idx11 + 1;
  function poserEtape(i, accepte) {
    run("StoryQuestManager.ensure();");
    game.unlockedTabs.village = true; game.unlockedTabs.dungeon = true;
    game.storyQuests.forest.currentStep = g.STORY_QUESTS.forest.steps.length;
    g.WorldTravel.arrive("desert", 1);
    var c = game.storyQuests.desert;
    c.currentStep = i; c.accepted = !!accepte; c.choices = {};
    game.dungeonTierCleared = { 1: true };
    game.explorationProgression = game.explorationProgression || {};
    game.explorationProgression.citeVague5 = false;
  }

  // Verrou : fermée à l'étape 11, ouverte à l'étape 12.
  game = freshCombat("knight");
  poserEtape(idx11, true);
  ok(g.DungeonManager.getLockReason(2) === "data" && !g.DungeonManager.isUnlocked(2), "étape 11 : la Cité est encore fermée");
  ok(!g.DungeonManager.isStoryTicketFree(2), "étape 11 : pas d'entrée offerte");
  poserEtape(idx12, true);
  ok(g.DungeonManager.isUnlocked(2), "étape 12 : la Cité s'ouvre");
  ok(g.DungeonManager.isStoryTicketFree(2), "étape 12 acceptée : l'entrée est offerte");
  poserEtape(idx12, false);
  ok(!g.DungeonManager.isStoryTicketFree(2), "étape 12 non acceptée : entrée payante");

  // La Tanière n'a pas changé de comportement.
  game = freshCombat("knight");
  run("StoryQuestManager.ensure();");
  var iF13 = g.STORY_QUESTS.forest.steps.map(function (st) { return st.id; }).indexOf("forest_13");
  game.storyQuests.forest.currentStep = iF13; game.storyQuests.forest.accepted = true;
  ok(g.DungeonManager.isStoryTicketFree(1), "Tanière : entrée offerte pendant forest_13");
  ok(!g.DungeonManager.isStoryTicketFree(3), "un donjon sans étape déclarée ne donne rien");

  // Relevé de la vague 5, sans toucher au compteur du donjon.
  game = freshCombat("knight");
  poserEtape(idx12, true);
  var step12 = g.STORY_QUESTS.desert.steps[idx12];
  ok(step12.id === "desert_12" && !step12.check(game), "vague 5 non franchie : étape non validée");
  game.dungeonRun = { active: true, dungeonId: 2, wave: 5, marks: [] };
  ok(!step12.check(game), "vague 5 en cours : pas encore");
  game.dungeonRun = { active: true, dungeonId: 1, wave: 9, marks: [] };
  ok(!step12.check(game), "vague 9 de la Tanière : ne compte pas");
  game.dungeonRun = { active: true, dungeonId: 2, wave: 6, marks: [] };
  ok(step12.check(game), "vague 5 franchie : étape validée");
  game.dungeonRun = { active: false, dungeonId: 2, wave: 0, marks: [] };
  ok(step12.check(game), "le drapeau survit à la fin du run");
})();

/* [112] v3.316.0 (W-4b) — Étape 13 « Le verre et le fer » : le palier d'équipement,
   la Forge au niveau 3 payée en Verre trempé, les trois compteurs. */
console.log("\n[112] v3.316.0 — Acte III, étape 13 : le palier d'équipement");
(function () {
  var F = g.VILLAGE_BUILDINGS.forge;
  ok(F.maxLevel === 3, "la Forge monte au niveau 3");
  var t3 = F.costTiers.filter(function (t) { return t.minLevel === 2; })[0];
  ok(!!t3 && t3.baseCost.verre_trempe > 0, "le niveau 3 se paie en Verre trempé");
  ok(g.WORLD_CAPS[1].village.forge === 3, "le plafond du Désert suit");
  ok(F.effectLabel(3) === "Reforge jusqu'au niveau 6 sur chaque emplacement", "Forge 3 : reforge jusqu'à 6");

  game = freshCombat("knight");
  var step = g.STORY_QUESTS.desert.steps.filter(function (st) { return st.id === "desert_13"; })[0];
  ok(!!step && step.act === "Acte III — La cité engloutie", "l'étape 13 existe");

  function poser(pieces, armeVerte, forge, reforge) {
    game.equipped = {};
    var slots = ["armor", "helmet", "gloves", "boots", "ring", "amulet"];
    if (armeVerte) game.equipped.weapon = { slot: "weapon", rarity: "green" };
    else game.equipped.weapon = { slot: "weapon", rarity: "common" };
    var n = pieces - (armeVerte ? 1 : 0);
    for (var i = 0; i < slots.length; i++) game.equipped[slots[i]] = { slot: slots[i], rarity: i < n ? "green" : "common" };
    game.village = game.village || {}; game.village.buildings = game.village.buildings || {};
    game.village.buildings.forge = { level: forge };
    g.ForgeManager.ensure();
    game.forge.levels.weapon = reforge;
  }

  poser(4, true, 3, 4);
  var p = g.storyPalierDesert(game);
  ok(p.pieces === 4 && p.armeVerte && p.forge === 3 && p.reforge === 4, "relevé du palier : 4 pièces, arme verte, Forge 3, reforge 4");
  ok(step.check(game), "palier complet : étape validée");

  poser(4, false, 3, 4);
  ok(!step.check(game), "quatre pièces mais arme commune : refusé");
  // v3.356.0 (D1) : 3 pièces dont l'arme, Forge 2, reforge 4
  poser(3, true, 2, 4);
  ok(step.check(game), "D1 : trois pièces dont l'arme, Forge 2, reforge 4 : validé");
  poser(2, true, 2, 4);
  ok(!step.check(game), "deux pièces : refusé");
  poser(3, true, 1, 4);
  ok(!step.check(game), "Forge 1 : refusé");
  poser(4, true, 3, 3);
  ok(!step.check(game), "arme reforgée à 3 : refusé");
  poser(6, true, 3, 6);
  ok(step.check(game), "au-delà du palier : validé aussi");

  poser(1, true, 1, 1);
  ok(/Inhabituels 1\/3/.test(step.progress(game)) && /Forge 1\/2/.test(step.progress(game)), "les compteurs disent où on en est (" + step.progress(game) + ")");
  ok(step.objectiveLabel === "3 emplacements Inhabituels dont l'arme, Forge 2, arme reforgée à 4", "l'objectif affiché suit le palier");
  // Une rareté supérieure compte : le palier est un plancher, pas une égalité.
  var avant = g.storyPalierDesert(game).pieces;
  game.equipped.boots = { slot: "boots", rarity: "rare" };
  ok(g.storyPalierDesert(game).pieces === avant + 1, "une pièce Rare compte pour le palier");
})();

/* [113] v3.317.0 (W-4c) — Étape 14 « La bête sous la dune » : élite répétable, Chitine des
   profondeurs, reforges 5 et 6, vague 10 du donjon. */
console.log("\n[113] v3.317.0 — Acte III, étape 14 : le Dard des profondeurs");
(function () {
  var d = g.ELITE_DB.dard_profondeurs;
  ok(!!d && d.baseId === "sandworm" && d.repeatable === true, "le Dard existe, base Ver des sables, répétable");
  ok(!!d.winResource && d.winResource.id === "chitine_profondeurs" && d.winResource.amount === 1, "il lâche une Chitine par victoire");
  ok(!!g.WAREHOUSE_RESOURCES.chitine_profondeurs && g.WAREHOUSE_RESOURCES.chitine_profondeurs.worldIndex === 1, "la Chitine est une ressource du Désert");
  var cite = g.DUNGEONS.filter(function (x) { return x.id === 2; })[0];
  ok(cite.eliteWaves[10] === "dard_profondeurs", "vague 10 de la Cité : le Dard");
  var sect = g.LIVING_MAPS.desert.sectors.filter(function (x) { return x.id === "bete_dune"; })[0];
  ok(sect.requiresStoryStep === "desert_14" && sect.content.repeatable === true, "la dune attend l'étape 14 et se rejoue");

  // Barème de reforge : la Chitine n'arrive qu'au-delà du niveau 4.
  game = freshCombat("knight");
  game.village = game.village || {}; game.village.buildings = game.village.buildings || {};
  game.village.buildings.forge = { level: 3 };
  g.ForgeManager.ensure();
  var attendus = [];
  for (var lvl = 0; lvl < 6; lvl++) {
    game.forge.levels.weapon = lvl;
    var c = g.ForgeManager.getCost("weapon");
    attendus.push(c && c.chitine_profondeurs ? c.chitine_profondeurs : 0);
  }
  ok(attendus[0] === 0 && attendus[1] === 0 && attendus[2] === 0 && attendus[3] === 0, "niveaux 1 à 4 : pas de Chitine");
  ok(attendus[4] === 1 && attendus[5] === 2, "niveau 5 : 1 Chitine ; niveau 6 : 2");
  game.village.buildings.forge = { level: 2 };
  game.forge.levels.weapon = 4;
  ok(g.ForgeManager.getCost("weapon") === null, "Forge 2 : la reforge 5 reste fermée");

  // L'étape se valide à la libération du secteur.
  game = freshCombat("knight");
  run("StoryQuestManager.ensure();");
  g.LivingMapManager.ensureDefaults();
  var step = g.STORY_QUESTS.desert.steps.filter(function (st) { return st.id === "desert_14"; })[0];
  ok(!!step && !step.check(), "dune non libérée : étape non validée");
  g.LivingMapManager.setState("desert", "bete_dune", "libere", "harnais");
  ok(step.check() && /1\/1/.test(step.progress()), "dune libérée : étape validée");
})();

/* [114] v3.318.0 — Élite SANS escorte : le groupe allié est rebâti au spawn, comme sur le
   chemin avec escorte. Trouvé au banc des élites de carte. */
