/* [117] v3.321.0 — boutique d'Éclats sans puissance : Sacoche, Clé, Doigté, Carte de l'éclaireur. */
console.log("\n[117] v3.321.0 — Boutique d'Éclats : plus de puissance, quatre effets utilitaires");
(function () {
  var D = g.DungeonManager;
  D.ensure();
  var savedLevels = game.dungeonShopLevels;
  var ids = g.DUNGEON_SHOP.map(function (i) { return i.id; }).sort().join(",");
  ok(ids === "d_cle,d_doigte,d_eclaireur,d_sacoche", "la boutique vend exactement les quatre articles retenus");
  ok(g.DUNGEON_SHOP.every(function (i) { return i.effect && i.perLevel > 0 && i.maxLevel > 0; }), "chaque article déclare son effet");

  /* Un vieux niveau de Lame ou d'Armure n'agit plus. */
  game.dungeonShopLevels = { d_power: 20, d_defense: 20, d_gold: 20, d_essence: 20 };
  var b = D.getShardShopBonuses();
  ok(b.power === 0 && b.defense === 0 && b.gold === 0 && b.essence === 0, "anciens niveaux achetés : aucun bonus de puissance");
  g.StatsSystem.recalcStats();
  var tap20 = game.tapMult;
  game.dungeonShopLevels = {};
  g.StatsSystem.recalcStats();
  ok(Math.abs(game.tapMult - tap20) < 1e-9, "les dégâts du héros ne dépendent plus de la boutique");

  /* Sacoche */
  var cite = D.getById(2);
  var base = D.getSpecialAmount(cite, 0);
  ok(base === 2, "Cité sans Sacoche : 2 Verres des dunes");
  game.dungeonShopLevels = { d_sacoche: 3 };
  ok(D.getSpecialAmount(cite, 0) === 5 && D.getSpecialAmount(cite, 1) === 7, "Sacoche 3 : +3, et les Marques s'y ajoutent");

  /* Clé de faille */
  /* v3.358.0 (D7) : la Clé ne réduit plus un prix de ticket, elle ajoute des sorties. Contrôles en [137]. */
  game.dungeonShopLevels = {};
  var c0 = D.getRunsPerDay();
  game.dungeonShopLevels = { d_cle: 2 };
  ok(D.getRunsPerDay() === c0 + 2, "Clé 2 : +2 sorties par jour (" + c0 + " → " + D.getRunsPerDay() + ")");

  /* Doigté : jamais sous une Sève */
  var item = { rarity: "rare", affixes: [{ stat: "tapMult", value: 0.05 }] };
  var savedCan = g.EnchantManager.canRerollRarity;
  g.EnchantManager.canRerollRarity = function () { return true; }; // niveau de l'Enchanteresse hors sujet ici
  game.dungeonShopLevels = {};
  var cost0 = g.EnchantManager.getCost(item, 0);
  game.dungeonShopLevels = { d_doigte: 3 };
  var cost3 = g.EnchantManager.getCost(item, 0);
  ok(cost0.seve_aeswyn === 2 && cost3.seve_aeswyn === 1, "Doigté 3 : relance d'un Rare à 1 Sève au lieu de 2 (jamais sous 1)");
  item.affixes[0].rerolls = 9; // 2 + 3 = 5 Sèves sans Doigté
  ok(g.EnchantManager.getCost(item, 0).seve_aeswyn === 2, "10e relance du même affixe : 5 → 2 Sèves");
  g.EnchantManager.canRerollRarity = savedCan;

  /* Carte de l'éclaireur */
  game.dungeonShopLevels = {};
  var cap0 = g.SceneRunManager.getPetiteAventureCap();
  game.dungeonShopLevels = { d_eclaireur: 2 };
  ok(g.SceneRunManager.getPetiteAventureCap() === cap0 + 2, "Carte 2 : deux Petites Aventures de plus par jour");

  game.dungeonShopLevels = savedLevels || {};
  g.StatsSystem.recalcStats();
})();

/* [118] v3.322.0 — Offrande et niveau de Mémoire (conception Offrande v1.2). */
console.log("\n[118] v3.322.0 — Offrande, Souvenirs, niveau de Mémoire et ses huit niveaux");
(function () {
  run("fullResetState(); game.playerName='Test'; game.heroId='knight'; EquipmentManager.recalcStats();");
  var M = g.MemoryManager;
  game.worldsEverReached = { 0: true };

  /* --- Fin de l'Ascension --- */
  ok(typeof g.AscensionManager === "undefined" && typeof g.getAetherBonuses === "undefined", "l'Ascension et les bonus d'Aether sont retirés (v3.412.0)");
  ok(typeof g.AETHER_SHOP === "undefined" && typeof g.buyAetherUpgrade === "undefined", "boutique d'Aether retirée (v3.355.0)");
  game.totalAetherEarned = 400; g.StatsSystem.recalcStats();
  var tap5 = game.tapMult, hp5 = game.heroMaxHp;
  game.totalAetherEarned = 0; g.StatsSystem.recalcStats();
  ok(Math.abs(game.tapMult - tap5) < 1e-9 && game.heroMaxHp === hp5, "l'Aether cumulé ne change pas les stats");

  /* --- Valeur d'Offrande --- */
  var com = g.generateEquipmentItem("ring", "common", 0), grn = g.generateEquipmentItem("ring", "green", 0);
  ok(M.getOfferingValue(com) === 1 && M.getOfferingValue(grn) === 3, "barème : Commun 1, Inhabituel 3");
  grn.fromShop = true;
  ok(M.getOfferingValue(grn) === 0, "objet acheté : aucun souvenir, 0 Aether (O9)");

  /* --- Sac à 25, sac plein -> offert, unique en dépassement --- */
  ok(g.getInventoryCap() === 25, "sac de base : 25 places");
  game.inventory = []; for (var i = 0; i < 25; i++) game.inventory.push(g.generateEquipmentItem("ring", "common", 0));
  var t0 = game.totalAetherEarned;
  var kept = g.addLootToInventory(g.generateEquipmentItem("ring", "common", 0));
  ok(kept === false && game.inventory.length === 25 && game.totalAetherEarned === t0 + 1, "sac plein : l'objet est offert (+1), pas perdu");
  var uni = g.EliteManager.buildUniqueLoot("araignee_marquee");
  ok(g.addLootToInventory(uni) === true && game.inventory.length === 26, "objet unique : entre en dépassement");
  game.gold = 999999;
  g.EquipShopManager.ensure();
  var art = g.generateEquipmentItem("ring", "common", 0); art.uid = "shop_t118"; art.price = 10; art.bought = false;
  game.equipShopStock = [art];
  var offre = art;
  if (offre) {
    var g0 = game.gold; g.EquipShopManager.buy(offre.uid);
    ok(game.gold === g0 && game.inventory.length === 26, "échoppe, sac plein : achat refusé (pas d'Aether gratuit)");
  } else ok(true, "échoppe vide : contrôle sauté");

  /* --- Offrir depuis le sac, Tout offrir --- */
  game.inventory = [com, uni]; var t1 = game.totalAetherEarned;
  g.EquipmentManager.sell(com.uid);
  ok(game.inventory.length === 1 && game.totalAetherEarned === t1 + 1, "Offrir : l'objet part, +1 Aether, pas d'or");
  game.inventory = [g.generateEquipmentItem("ring", "green", 0), uni];
  g.sellAllInventory();
  ok(game.inventory.length === 1 && game.inventory[0] === uni, "Tout offrir : l'arme d'élite reste");
  ok(game.memory.firstOffering === true, "première Offrande notée (ligne du Veilleur)");

  /* --- Jauge, coûts, plafond par monde --- */
  game.totalAetherEarned = 0; game.memory = null; M.ensure();
  M.souvenir("storyStep");
  ok(game.totalAetherEarned === 1 && game.aether === undefined, "Souvenir d'étape : +1 à la jauge (v3.358.0 : plus de solde d'Aether)");
  game.totalAetherEarned = 37;
  ok(M.getLevel() === 3, "37 Aether : niveau 3 (coûts 5/8/11/14)");
  game.totalAetherEarned = 500;
  ok(M.getLevel() === 4 && M.getProgress().capped === true, "Forêt seule : plafond à 4 niveaux");
  game.worldsEverReached = { 0: true, 1: true };
  ok(M.getLevel() === 8, "Désert atteint : jusqu'au niveau 8");

  /* --- Choix, reprises --- */
  ok(M.choose(1, "sac_profond") === true && g.getInventoryCap() === 50, "Sac profond : 50 places");
  game.gold = 10000; /* v3.358.0 (D7) : la reprise se paie en or */
  ok(M.getRepriseCost() === 500, "première reprise : 500 or");
  M.choose(1, "reserve_alchimiste");
  ok(game.gold === 9500 && M.getRepriseCost() === 1500 && g.getPotionStockCap() === 15 && g.getInventoryCap() === 25,
    "reprise payée, prix ×3 ; Réserve d'alchimiste : 15 potions, le sac revient à 25");
  ok(M.choose(9, "x") === false && M.choose(2, "inconnu") === false, "choix invalides refusés");

  /* --- Effets --- */
  var slots0 = g.getGrimoireSlotCount(game.worldsEverReached);
  M.choose(2, "grimoire_etendu");
  ok(g.getGrimoireSlotCount(game.worldsEverReached) === slots0 + 1, "Grimoire étendu : une règle active de plus");
  // v3.323.0 : la Fiole quitte le niveau 3 (Ruines plus tard) ; Cuisine de campagne à la place
  ok(M.choose(3, "fiole_reserve") === false && g.getSortiePotionCap() === 2, "Fiole de réserve : plus proposée au niveau 3, 2 potions par sortie");
  M.choose(3, "cuisine_campagne");
  game.warehouse = game.warehouse || {}; run("WarehouseManager.addResource('petite_ration', 2, true)");
  game.heroHp = 1;
  run("CampManager.eatRation('petite_ration')");
  ok(game.heroHp === 1 + Math.floor(game.heroMaxHp * 0.35 * 1.25), "Cuisine de campagne : Petite ration à 43,75 % au lieu de 35 %");
  M.choose(4, "memoire_vive");
  var t2 = game.totalAetherEarned;
  M.gainAether(4); ok(game.totalAetherEarned === t2 + 5, "Mémoire vive : 4 -> 5");
  M.gainAether(1); M.gainAether(1); M.gainAether(1);
  ok(game.totalAetherEarned === t2 + 5 + 3, "Mémoire vive : les fractions s'accumulent (3 × 1,25 = 3 + reste)");
  M.choose(5, "seconde_gorgee"); M.choose(6, "etal_garni"); M.choose(8, "main_forgeron");
  ok(g.EquipShopManager.getShopSize(0) === run("EQUIP_SHOP_SIZE") + 1, "Étal garni : +1 objet en vitrine");
  M.choose(7, "voie_libre");
  ok(M.isVoieFreeToday() === true, "Voie libre : un changement gratuit aujourd'hui");
  M.useVoieFree();
  ok(M.isVoieFreeToday() === false, "...et un seul par jour");
  M.choose(2, "repos_camp");
  ok(g.getCampOfflineRegenCap() === 0.75, "Repos du camp : 75 % hors ligne");

  /* --- Fidélité : retour après KO --- */
  game.gold = 1e7;
  M.choose(3, "fidelite_wenna");
  g.CompanionManager.unlock("wenna");
  var st = g.CompanionManager.state("wenna"); st.hp = 0;
  g.CompanionManager.onCombatStart();
  ok(st.hp === g.CompanionManager.maxHpOf("wenna"), "Fidélité de Wenna : retour à 100 % après un KO");

  /* --- Sauvegarde --- */
  var d = g.buildSaveData();
  ok(d.memory && d.memory.choices[3] === "fidelite_wenna", "buildSaveData : les choix de Mémoire sont écrits");
  game.memory = null; g.restoreBaseState(d);
  ok(game.memory && game.memory.choices[1] === "reserve_alchimiste" && game.memory.reprises >= 1, "restoreBaseState : la Mémoire est relue");
  run("fullResetState()");
  ok(game.memory && Object.keys(game.memory.choices).length === 0 && game.totalAetherEarned === 0, "fullResetState : la Mémoire repart de zéro");

  /* --- Hauts faits, Élixir retiré --- */
  // v3.338.0 : les trois hauts faits de Mémoire passent dans la catégorie Collection (mêmes identifiants)
  var ach = g.ACHIEVEMENTS_DB.filter(function (a) { return /^ach_ascend_/.test(a.id); });
  ok(ach.length === 3 && ach.map(function (a) { return a.target; }).join(",") === "1,4,8", "Hauts faits : niveaux de Mémoire 1, 4 et 8");
  game.potionsOwned = game.potionsOwned || {}; game.potionsOwned.elixir_aether = 3;
  var liste = null, err = null;
  try { liste = g.getOwnedPotionsList(); } catch (e) { err = e; }
  ok(!err && !liste.some(function (x) { return x && x.potion && x.potion.id === "elixir_aether"; }), "stock d'Élixirs d'une vieille sauvegarde : ignoré sans erreur");
  ok(!!g.TALENT_TREES && !!g.TALENT_TREES.knight, "talents par classe chargés (v3.327.0)");
})();

/* [119] v3.324.0 — Admin : compagnons, Petites Aventures, Histoire ; carte d'un autre héros. */
console.log("\n[119] v3.324.0 — Admin (compagnons, Petites Aventures, avance d'Histoire) et carte vivante d'un autre héros");
(function () {
  run("fullResetState(); game.playerName='Test'; game.heroId='knight'; EquipmentManager.recalcStats();");
  var game = g.game;

  /* --- Compagnons --- */
  g.adminRecruitCompanions();
  ok(g.CompanionManager.isUnlocked("wenna") && g.CompanionManager.isUnlocked("maddoc"), "recrutement : Wenna et Maddoc recrutés");
  ok(g.CompanionManager.state("maddoc").voie === "tronc", "Maddoc sans voie : voie par défaut (tronc)");
  ok(g.isTabUnlocked("companions") && g.CompanionManager.partyIds().length === 2, "onglet Compagnons ouvert, deux compagnons présents");
  ok(g.buildAdminCompanionsHTML().indexOf("recruté") >= 0, "carte Admin : état affiché");

  /* --- Petites Aventures --- */
  var SR = g.SceneRunManager, cap = SR.getPetiteAventureCap();
  game.explorationProgression.petiteAventure = { day: SR._today(), count: cap };
  ok(!SR.canStartPetiteAventureToday(), "cap du jour atteint avant le bouton");
  g.adminAddPetiteAventure(1);
  ok(SR.canStartPetiteAventureToday() && cap - SR.petiteAventureCountToday() === 1, "+1 tentative : une Petite Aventure de plus");
  g.adminAddPetiteAventure(5);
  ok(cap - SR.petiteAventureCountToday() === 6, "+5 tentatives : au-delà du cap");
  g.adminResetPetiteAventure();
  ok(SR.petiteAventureCountToday() === 0, "remise à zéro du jour");
  game.explorationProgression.petiteAventure = { day: "Mon Jan 01 2001", count: 3 };
  g.adminAddPetiteAventure(1);
  ok(cap - SR.petiteAventureCountToday() === cap + 1, "jour périmé : repart du cap du jour, +1");

  /* --- Histoire : valider l'étape en cours --- */
  run("fullResetState(); game.playerName='Test'; game.heroId='knight'; EquipmentManager.recalcStats();");
  game = g.game;
  var SQ = g.StoryQuestManager;
  var first = SQ.getCurrentStep("forest").id;
  ok(g.adminForceStoryStep(true) === first && SQ.getState("forest").currentStep === 1, "valider : l'étape en cours est réclamée");
  ok(SQ.getCurrentStep("forest").check === g.STORY_QUESTS.forest.steps[1].check, "le check d'origine est remis en place");
  ok(typeof g.openQuestCompletePopup === "function" && g.showToast.toString().indexOf("function () {}") < 0, "popup et toast restaurés après l'avance muette");

  /* --- Histoire : avancer jusqu'à desert_09 --- */
  var sel = { value: "desert_09" }, oldGet = g.document.getElementById;
  g.document.getElementById = function (id) { return id === "admin-story-target" ? sel : oldGet(id); };
  g.adminJumpToStoryStep();
  g.document.getElementById = oldGet;
  var cur = SQ.getCurrentStep("desert");
  ok(SQ.isChapterCompleted("forest"), "Forêt terminée");
  ok(cur && cur.id === "desert_09" && !SQ.getState("desert").accepted, "arrivée sur desert_09, pas encore acceptée");
  ok(g.WorldManager.worldIndex === 1, "la traversée a posé le monde du Désert");
  var ep = game.explorationProgression;
  ok(ep.desertCrossingCompleted && ep.desertReached && ep.templeDescended && ep.desertPaCompleted && ep.outreFilled, "drapeaux de traversée, Temple et Petite Aventure posés");
  ok(game.dungeonTierCleared[1] === true, "Tanière marquée franchie (forest_14)");
  ok(game.adventureQuestsCompleted.aq_story_coeur && game.adventureQuestsCompleted.aq_desert_gouffre, "quêtes d'aventure liées marquées terminées");
  ok(g.LivingMapManager.getState("desert", "steles").liberatedCount > 0 && g.LivingMapManager.getState("desert", "steles").state === "recouvert" && g.LivingMapManager.isLiberated("desert", "porte_temple"), "secteurs liés libérés (stèles reprises par le sable : noms déterrés)");
  ok(SQ.getChoice("noms") === "deterrer" && g.CompanionManager.state("maddoc").voie === "tronc", "choix en attente : première option");
  ok(g.CompanionManager.isUnlocked("wenna") && g.CompanionManager.isUnlocked("maddoc"), "compagnons recrutés par l'Histoire");
  ok(!!SQ.getState("forest").tutorialsSeen.forest_wenna, "tutoriels des étapes passées notés comme vus");

  /* --- Refus pendant une activité --- */
  game.huntRun = { active: true };
  var before = SQ.getState("desert").currentStep;
  g.adminValidateStoryStep();
  ok(SQ.getState("desert").currentStep === before, "activité en cours : validation refusée");
  game.huntRun = { active: false };

  /* --- Carte vivante d'un autre héros --- */
  var slot = 1;
  g.HeroSlotManager.getActiveSlot = function () { return slot; };
  g.game.activeTab = "campement";
  g.openLivingMap("desert");
  ok(g.isLivingMapOpen(), "carte du Désert ouverte par le héros 1");
  g.buildMapHTML();
  ok(g.isLivingMapOpen(), "même héros : la carte reste ouverte");
  slot = 2;
  g.buildMapHTML();
  ok(!g.isLivingMapOpen(), "autre héros : la carte est refermée");
  slot = 1;
  g.openLivingMap("desert");
  game.storyQuests.desert.currentStep = 0; game.storyQuests.forest.currentStep = 0;
  g.buildMapHTML();
  ok(!g.isLivingMapOpen(), "carte pas encore atteinte par ce héros : refermée");
})();

/* [120] v3.325.0 — Plafond du Terrain d'entraînement par acte (plan C-1). */
console.log("\n[120] v3.325.0 — Plafond du Terrain d'entraînement par acte");
(function () {
  run("fullResetState(); game.playerName='Test'; game.heroId='mage'; EquipmentManager.recalcStats();");
  var game = g.game, WC = g.WorldCaps, VB = g.VillageBuildingManager;
  var F = g.STORY_QUESTS.forest.steps, D = g.STORY_QUESTS.desert.steps;
  function idx(steps, id) { return steps.findIndex(function (s) { return s.id === id; }); }
  VB.ensure();
  function pose(fStep, dStep, worlds) {
    g.StoryQuestManager.ensure();
    game.storyQuests.forest.currentStep = fStep; game.storyQuests.forest.skipped = false;
    game.storyQuests.desert.currentStep = dStep;
    game.worldsEverReached = worlds; g.WorldManager.worldIndex = 0;
    game.village.buildings.training.level = 0;
  }

  pose(0, 0, { 0: true });
  ok(WC.getVillageCap("training") === 0 && VB.getMaxLevel("training") === 0, "Forêt, acte I : Terrain 0 (entraînement 20)");
  ok(VB.getWorldCapLabel("training") === "S'ouvre à l'acte II de la Forêt enchantée", "libellé : " + VB.getWorldCapLabel("training"));
  pose(idx(F, "forest_06"), 0, { 0: true });
  ok(WC.getVillageCap("training") === 2, "Forêt, acte II (forest_06) : Terrain 2");
  pose(idx(F, "forest_crossing"), 0, { 0: true });
  ok(WC.getVillageCap("training") === 4, "Forêt, acte III (Lisière) : Terrain 4");
  pose(F.length, 0, { 0: true });
  game.village.buildings.training.level = 4;
  ok(WC.getVillageCap("training") === 4 && VB.getWorldCapLabel("training") === "Suite à l'acte I du Désert oublié", "Forêt finie, Désert pas atteint : 4, suite à l'acte I du Désert");

  pose(F.length, 0, { 0: true, 1: true });
  ok(WC.getVillageCap("training") === 5, "Désert, acte I : Terrain 5 (entraînement 70)");
  game.village.buildings.training.level = 5;
  ok(VB.getWorldCapLabel("training") === "Suite à l'acte II du Désert oublié", "libellé : " + VB.getWorldCapLabel("training"));
  game.village.buildings.training.level = 5;
  ok(g.getTrainingCapLevels() === 70, "Terrain 5 : plafond d'entraînement 70");
  pose(F.length, idx(D, "desert_06"), { 0: true, 1: true });
  ok(WC.getVillageCap("training") === 7, "Désert, acte II (desert_06) : Terrain 7");
  pose(F.length, idx(D, "desert_11"), { 0: true, 1: true });
  ok(WC.getVillageCap("training") === 9, "Désert, acte III (desert_11) : Terrain 9");

  pose(F.length, 0, { 0: true, 1: true });
  game.village.buildings.training.level = 9;
  ok(VB.getMaxLevel("training") === 9 && VB.isMaxLevel("training"), "Terrain 9 déjà construit à l'acte I : rien n'est repris, pas de niveau au-delà");
  pose(0, 0, { 0: true, 1: true, 2: true, 3: true }); // v3.428.0 : les Ruines ont leur entrée, la Crypte non
  ok(WC.getTrainingActCap() === Infinity, "monde sans entrée d'acte : aucun plafond d'acte");
  game.storyQuests.forest.skipped = true; game.worldsEverReached = { 0: true };
  ok(WC.getVillageCap("training") === 4, "chapitre de la Forêt court-circuité : Forêt au complet (4)");
  ok(WC.getVillageCap("hall") === 4, "les autres bâtiments gardent le plafond du monde");
})();

/* [121] v3.326.0 — Lot C-2 : dégâts des ennemis de quête (enemyPowerMult) et réglages. */
console.log("\n[121] v3.326.0 — Lot C-2 : enemyPowerMult et recalage des combats");
(function () {
  run("fullResetState(); game.playerName='Test'; game.heroId='knight';");
  var Q = g.QuestEnemyManager, A = g.ADVENTURE_QUESTS;
  var genSave = g.WorldManager.generateEnemy;
  g.WorldManager.generateEnemy = function () { return { id: "x", hp: 100, maxHp: 100, isBoss: false, stats: { power: 20 } }; };
  var e = Q.spawnFor(A.aq_desert_dunes, false);
  ok(e.stats.power === 80 && e.maxHp === 150, "dunes : puissance ×4 (20 -> " + e.stats.power + "), PV ×1,5");
  var sans = Q.spawnFor(A.aq_story_premier_sang, false);
  ok(sans.stats.power === 20, "quête sans enemyPowerMult : puissance inchangée");
  // Rencontre scriptée : la copie réduite porte l'id, la puissance est lue sur la donnée d'origine
  var copie = { id: "aq_desert_nuee", worldId: "desert", adventureIndex: 0 };
  ok(Q.spawnFor(copie, false).stats.power === 130, "rencontre scriptée (nuée) : ×6,5 lu sur ADVENTURE_QUESTS");
  g.WorldManager.generateEnemy = function () { return { id: "b", hp: 100, maxHp: 100, isBoss: true, stats: { power: 20 } }; };
  A.aq_desert_dunes.bossPowerMult = 2;
  ok(Q.spawnFor(A.aq_desert_dunes, true).stats.power === 40, "bossPowerMult règle le boss à part");
  delete A.aq_desert_dunes.bossPowerMult;
  g.WorldManager.generateEnemy = genSave;
  ok(Q.getPowerMult(null) === 1 && Q.getPowerMult({ id: "inconnue" }) === 1, "sans donnée : ×1");

  // Les réglages mesurés au banc (tools/sim/plafond-bench.js)
  var E = g.ELITE_DB, D = g.DUNGEONS;
  ok(E.serment_armure.statMult.power === 4 && E.serment_armure.statMult.endurance === 3.5, "serment sous l'armure : 4 / 3,5");
  ok(E.dard_profondeurs.statMult.power === 3.5 && E.dard_profondeurs.statMult.endurance === 3.5, "dard des profondeurs : 3,5 / 3,5 (v3.357.0, réglé sur le héros de campagne)");
  ok(E.ronce_ardente.statMult.power === 1.4 && E.ronce_ardente.statMult.endurance === 2.8, "ronce ardente : 1,4 / 2,8");
  ok(D.filter(function (d) { return d.id === 1; })[0].difficultyMult === 1.8, "Tanière du Basilic : difficulté 1,8");
  ok(A.aq_story_coeur.enemyPowerMult === 2.5 && A.aq_forest_depths.enemyPowerMult === 6, "Cœur ×2,5, orc de l'étape 15 ×6");
  ok(A.aq_desert_gouffre.encounterHpMult === 2.4 && A.aq_desert_gouffre.enemyPowerMult === 5.5, "gouffre : PV ×2,4, puissance ×5,5");
  ok(A.aq_desert_nuee.encounterHpMult === 1.9 && A.aq_desert_nuee.enemyPowerMult === 6.5, "nuée : PV ×1,9, puissance ×6,5");
})();

/* [122] v3.327.0 — Talents par classe (conception Talents v1.1, T1 à T14). */
console.log("\n[122] v3.327.0 — Talents par classe : points plafonnés par acte, arbre, crochets, migration");
(function () {
  var TM = g.TalentManager, WC = g.WorldCaps, SQ = g.StoryQuestManager;
  var game = freshCombat("knight"); giveWeapon();
  var reachSave = SQ.isStepReached, worldSave = WC.getReachedWorldIndex;
  function atAct(world, steps) {
    WC.getReachedWorldIndex = function () { return world; };
    SQ.isStepReached = function (id) { return steps.indexOf(id) !== -1; };
  }
  function restore() { SQ.isStepReached = reachSave; WC.getReachedWorldIndex = worldSave; }

  // --- Plafond par acte, réserve ---
  try {
    atAct(0, ["forest_01"]);
    ok(WC.getTalentActCap() === 0, "Forêt I-II : plafond 0");
    atAct(0, ["forest_01", "forest_crossing"]);
    ok(WC.getTalentActCap() === 5, "Forêt III-IV : plafond 5");
    atAct(1, ["desert_01", "desert_06", "desert_11"]);
    ok(WC.getTalentActCap() === 11, "Désert III : plafond 11");
    atAct(1, ["desert_01"]);
    game.heroLevel = 12; game.talents = {}; TM.sync();
    ok(TM.cap() === 7 && TM.earned() === 11 && TM.available() === 7 && TM.reserve() === 4,
      "niveau 12 au Désert I : 7 points à placer, 4 en réserve");
    ok(game.talentPoints === 7, "game.talentPoints suit les points disponibles");
    atAct(5, []);
    ok(TM.cap() === Infinity && TM.available() === 11, "monde sans table : pas de plafond");

    // --- Règles de l'arbre (T13 libre, T14 tronc à 2) ---
    atAct(1, ["desert_01"]);
    game.talents = {};
    ok(/tronc/.test(TM.blockReason("k_elan")), "voies fermées tant que le tronc n'a pas 2 points");
    ok(TM.buy("k_cuirasse") && TM.buy("k_cuirasse"), "Cuirasse : deux rangs");
    ok(TM.rank("k_cuirasse") === 2 && /maximum/.test(TM.blockReason("k_cuirasse")), "rang maximum atteint à 2");
    ok(TM.buy("k_curee"), "voie ouverte à 2 points de tronc, ordre libre (Curée d'abord)");
    ok(/Demande 3/.test(TM.blockReason("k_sentence")), "la clé demande 3 nœuds de sa voie");
    TM.buy("k_elan"); TM.buy("k_brise_os");
    ok(TM.buy("k_sentence"), "clé Sentence apprise après 3 nœuds");
    ok(TM.available() === 1, "7 points : 1 restant");
    TM.buy("k_rancune");
    ok(TM.isClosed("k_bastion"), "l'autre clé (Bastion) est fermée");
    ok(/Plafond|Pas de point/.test(TM.blockReason("k_mur")), "plus de point : achat refusé");

    // --- Le kit réécrit (donnée) ---
    var kit = g.getClassSkills("knight");
    ok(kit.actions.skill1.resourceCost === 12 && kit.actions.skill3.cooldownRounds === 2
      && kit.actions.skill3.conditions.enemyHpPercentBelowOrEqual === 0.45, "Élan, Sentence et Curée lus dans le kit");
    ok(kit.actions.skill2.effects.filter(function (e) { return e.type === "enemyVulnerability"; })[0].value === 0.30, "Brise-os : vulnérabilité 30 %");
    ok(g.CLASS_SKILLS.knight.actions.skill1.resourceCost === 18, "la donnée d'origine n'est jamais modifiée");
    ok(g.getClassSkills("mage").actions.skill1.resourceCost === 18, "une autre classe garde son kit");

    // --- Remise à zéro gratuite, hors run ---
    var gold = game.gold = 500;
    game.adventureQuestRun.active = true;
    ok(!TM.respec() && TM.spent() === 7, "remise à zéro refusée pendant une sortie");
    game.adventureQuestRun.active = false;
    ok(TM.respec() && TM.spent() === 0 && game.gold === gold && TM.available() === 7, "remise à zéro gratuite : 7 points rendus, or intact");
  } finally { restore(); }

  // --- Crochets --- (plafond levé et héros niveau 30 : sync() retire un surplus au-delà du plafond)
  var capSave = TM.cap;
  TM.cap = function () { return Infinity; };
  var setTalents = function (gm, t) { gm.heroLevel = 30; gm.talents = t; TM.afterChange(); };
  function knight(t) {
    var gm = freshCombat("knight"); giveWeapon();
    setTalents(gm, t);
    gm.enemy.chargeIn = 99; gm.enemy.engageIn = 0; gm.enemy.hp = gm.enemy.maxHp = 100000;
    gm.heroHp = gm.heroMaxHp = 100000;
    return gm;
  }
  game = knight({ k_sang_chaud: 1 });
  game.classResource.current = 0; g.CombatEngine.spawnEnemy();
  ok(game.classResource.current >= 25, "Sang chaud : 25 Rage à l'ouverture d'un combat");

  game = knight({ k_rancune: 1 });
  game.classResource.current = 0;
  g.TalentManager.onHeroStruck({ enemy: game.enemy, taken: 100, blocked: 0, evaded: false, defenseType: null });
  ok(game.classResource.current === 10, "Rancune : 15 % des dégâts, plafonné à 10");

  game = knight({ k_riposte: 1 });
  var hp0 = game.enemy.hp;
  TM.onHeroStruck({ enemy: game.enemy, taken: 50, blocked: 100, evaded: false, defenseType: "damageReduction" });
  ok(hp0 - game.enemy.hp > 0, "Riposte : renvoie une part des dégâts bloqués (" + Math.round(hp0 - game.enemy.hp) + ")");

  game = knight({ k_soif_bourreau: 1 });
  game.classResource.current = 0; TM.onEnemyKilled(game.enemy);
  ok(game.classResource.current === 20, "Soif du bourreau : +20 Rage par ennemi tué");

  game = knight({ k_bastion: 1 });
  g.CombatEngine.heroAction("defense");
  ok(TM.basicGainMult() === 2, "Bastion : Rage doublée pendant la Garde");

  var gm = freshCombat("ranger"); giveWeapon(); setTalents(gm, { a_tir_mortel: 1 });
  gm.classCooldowns.archer_piercing_shot = 3; TM.onHeroCrit();
  ok(gm.classCooldowns.archer_piercing_shot === 2, "Tir mortel : un critique réduit la recharge de Tir perforant");
  setTalents(gm, { a_contre_tir: 1, a_danse_ombres: 1 });
  gm.enemy.hp = gm.enemy.maxHp = 100000; gm.heroGauge = 0;
  var eh = gm.enemy.hp;
  TM.onHeroStruck({ enemy: gm.enemy, taken: 0, blocked: 0, evaded: true, defenseType: "evasion" });
  ok(gm.enemy.hp < eh, "Contre-tir : un coup esquivé déclenche une frappe");
  ok(gm.heroGauge >= 25, "Danse des ombres : +25 de jauge à l'esquive");
  setTalents(gm, { a_marque_chasseur: 1, a_nuee_fleches: 1 });
  var ak = g.getClassSkills("archer");
  ok(ak.actions.skill2.hits === 4 && ak.actions.skill1.effects.some(function (e) { return e.type === "enemyVulnerability"; }),
    "Nuée de flèches (4 coups) et Marque du chasseur (vulnérabilité) dans le kit");

  var mg = freshCombat("mage"); giveWeapon(); setTalents(mg, { m_reserve: 1 });
  ok(mg.classResource.max === 120, "Réserve : le Mana max passe à 120 sur l'état existant");
  setTalents(mg, { m_surtension: 1 }); mg.classResource.current = 90;
  ok(Math.abs(TM.heroDamageMult(null, mg.enemy) - 1.1) < 1e-9, "Surtension : +10 % au-dessus de 80 Mana");
  setTalents(mg, { m_attiser: 1, m_incendie: 1 });
  mg.enemy.dot = { perRound: 10, rounds: 2 };
  TM.afterAction({ id: "mage_arcane_blast" }, mg.enemy);
  ok(mg.enemy.dot.rounds === 3, "Attiser : la brûlure dure un round de plus");
  ok(Math.abs(TM.heroDamageMult({ id: "mage_arcane_nova" }, mg.enemy) - 1.25) < 1e-9, "Incendie : Déflagration +25 % sur une cible qui brûle");
  setTalents(mg, { m_brasier: 1 });
  TM.onEnemyKilled(mg.enemy);
  ok(!!mg._talentBurnPending, "Brasier : la brûlure attend le prochain ennemi");
  g.CombatEngine.spawnEnemy();
  ok(mg.enemy.dot && mg.enemy.dot.perRound === 10 && !mg._talentBurnPending, "...et passe à l'ennemi suivant");
  setTalents(mg, { m_surcharge: 1, m_echo_barriere: 1 });
  mg.enemy.hp = mg.enemy.maxHp = 100000; mg.classResource.current = 0;
  TM.onDefenseStart();
  TM.onHeroStruck({ enemy: mg.enemy, taken: 60, blocked: 40, evaded: false, defenseType: "damageAbsorption" });
  ok(mg.classResource.current === 10, "Écho de barrière : 25 % de l'absorbé en Mana");
  var mh = mg.enemy.hp;
  TM.onDefenseEnd({ effectType: "damageAbsorption" });
  ok(mh - mg.enemy.hp >= 40, "Surcharge : la Barrière explose à la fin (" + Math.round(mh - mg.enemy.hp) + ")");
  TM.cap = capSave;

  // --- v3.328.0 (T15) : un peu de survie pour Bourreau et Faucon ---
  TM.cap = function () { return Infinity; };
  var kb = freshCombat("knight"); giveWeapon(); setTalents(kb, { k_elan: 1 });
  kb.enemy.chargeIn = 99; kb.enemy.engageIn = 0; kb.enemy.hp = kb.enemy.maxHp = 100000;
  ok(g.getClassSkills("knight").actions.skill1.healMaxHpPct === 0.02, "Élan : Frappe lourde soigne 2 % des PV max (donnée)");
  kb.classResource.current = 100; kb.heroHp = Math.floor(kb.heroMaxHp / 2);
  var hpK = kb.heroHp; g.ClassCombatManager.useSkill("skill1", null);
  ok(kb.heroHp >= hpK + Math.floor(kb.heroMaxHp * 0.02), "Élan : le soin est appliqué en combat");
  var rb = freshCombat("ranger"); giveWeapon(); var pvSans = rb.heroMaxHp;
  setTalents(rb, { a_tir_ajuste: 1 });
  ok(rb.heroMaxHp > pvSans * 1.08, "Visée posée : +10 % de PV max (" + Math.floor(pvSans) + " -> " + Math.floor(rb.heroMaxHp) + ")");
  TM.cap = capSave;

  // --- Migration (T10) ---
  run("fullResetState(); game.heroId='knight';");
  g.game.talentsV2 = false; g.game.heroLevel = 9; g.game.heroXpToNext = 851;
  g.game.talents = { t_sharpened_blades: 3, t_regenerate: 2 };
  TM.migrate();
  ok(g.game.talentsV2 === true && Object.keys(g.game.talents).length === 0, "migration : anciens talents retirés");
  ok(g.game._talentsMigrationNotice === true, "migration : message annoncé une fois");
  ok(g.game.heroXpToNext === g.getHeroXpRequiredForLevel(9), "migration : palier d'XP recalculé sur la courbe linéaire");
  var data = run("buildSaveData()");
  ok(data.talentsV2 === true, "talentsV2 sauvegardé");
  run("fullResetState();");
  ok(g.game.talentsV2 === true, "partie neuve : rien à migrer");

  // --- Retraits ---
  ok(g.getHeroXpRequiredForLevel(1) === 30 && g.getHeroXpRequiredForLevel(10) === 120, "courbe d'XP linéaire : 30, puis +10 par niveau");
  var src = require("fs").readFileSync(ROOT + "/js/main/game-loop.js", "utf8");
  ok(src.indexOf("t_regenerate") === -1 && src.indexOf("t_interest") === -1, "plus d'Essence cachée ni d'or passif");
})();

/* [123] v3.327.1 — Histoire d'une partie neuve au rechargement ; import d'une sauvegarde à un seul héros. */
console.log("\n[123] v3.327.1 — Partie neuve avancée sans rechargement ; import à un seul héros");
(function () {
  run("fullResetState(); game.playerName='H'; game.heroId='knight'; StoryQuestManager.ensure();");
  ok(g.game.storyQuests.forest.migratedV31078 === true, "un chapitre neuf naît déjà migré (v3.107.8)");
  g.game.storyQuests.forest.currentStep = 11;
  var d = run("buildSaveData()");
  run("restoreBaseState(" + JSON.stringify(JSON.stringify(d)) + " ? JSON.parse(" + JSON.stringify(JSON.stringify(d)) + ") : null);");
  ok(g.game.storyQuests.forest.currentStep === 11, "rechargée, la partie reste à l'étape 11 (avant : reculait à 10)");

  // Import au format à un seul héros : les anciens talents sont migrés comme au chargement
  run("fullResetState(); game.playerName='I'; game.heroId='knight';");
  var old = run("buildSaveData()");
  old.talents = { t_sharpened_blades: 3 }; old.talentsV2 = false;
  var confirmSave = g.showConfirmModal;
  g.showConfirmModal = function (t, m, i, cb) { cb(); };
  try { g.applyImportedSave(old); } finally { g.showConfirmModal = confirmSave; }
  ok(g.game.talentsV2 === true && !g.game.talents.t_sharpened_blades, "import à un seul héros : anciens talents retirés, drapeau posé");
})();

/* [124] v3.329.0 — Bandeau « Il approche » : plus réécrit à chaque image. */
console.log("\n[124] v3.329.0 — Bandeau d'alerte et rangées : réécriture seulement si le contenu change");
(function () {
  var writes = 0, inner = "";
  var host = { firstChild: null };
  Object.defineProperty(host, "innerHTML", {
    get: function () { return inner; },
    set: function (v) { writes++; inner = v; host.firstChild = v ? { n: writes } : null; }
  });
  g.setHtmlIfChanged(host, "<button>Il approche</button>");
  g.setHtmlIfChanged(host, "<button>Il approche</button>");
  g.setHtmlIfChanged(host, "<button>Il approche</button>");
  ok(writes === 1, "même contenu trois fois : une seule écriture (" + writes + ")");
  g.setHtmlIfChanged(host, "<button>Il charge !</button>");
  ok(writes === 2, "contenu changé : réécrit");
  host.innerHTML = ""; writes = 1;
  g.setHtmlIfChanged(host, "<button>Il charge !</button>");
  ok(writes === 2, "contenu vidé par ailleurs : réécrit même si la chaîne est la même");
  var src = require("fs").readFileSync(ROOT + "/js/ui/combat-view.js", "utf8");
  ok(/setHtmlIfChanged\(document\.getElementById\("combat-alert-bar"\)/.test(src), "le bandeau passe par setHtmlIfChanged");
  var grp = require("fs").readFileSync(ROOT + "/js/ui/combat-group-view.js", "utf8");
  ok(grp.indexOf("host.innerHTML === html") === -1, "rangées d'ennemis et d'alliés : plus de comparaison à innerHTML");
})();

/* [125] v3.330.0 — Économie du village (E1 à E6, conception Économie du village v1.1). */
console.log("\n[125] v3.330.0 — Plafond de stock brut, niveaux d'Histoire, Bloc taillé, vivres, fin de la vente");
(function () {
  run("fullResetState(); game.playerName='E'; game.heroId='knight'; VillageBuildingManager.ensure();");
  var W = g.WarehouseManager, VBM = g.VillageBuildingManager, SQ = g.StoryQuestManager;
  var reachSave = SQ.isStepReached;
  function reached(list) { SQ.isStepReached = function (id) { return list === true || list.indexOf(id) !== -1; }; }
  try {
    // --- E1 : plafond de stock brut ---
    ok(W.getCap("pierre") === 500, "E1 : pierre plafonnée à 500 sans Entrepôt");
    g.game.village.buildings.warehouse = { level: 6 };
    ok(W.getCap("pierre") === 2000 && W.getCap("viande") === 2000, "E1 : 2 000 avec l'Entrepôt 6 (plafond du Désert)");
    ok(W.getCap("seve_aeswyn") === Infinity, "E1 : une ressource rare (special) n'est pas concernée");
    g.game.village.buildings.warehouse = { level: 0 };
    g.game.resources.bois = 480;
    ok(W.addResource("bois", 100, true) === 20 && g.game.resources.bois === 500, "E1 : on ne dépasse pas le plafond (20 rentrent sur 100)");
    g.game.resources.fer = 3000;
    ok(W.addResource("fer", 50, true) === 0 && g.game.resources.fer === 3000 && W.getFreeSpace("fer") === 0, "E1 a1 : un stock ancien au-dessus est gardé, rien ne rentre");
    // récolte partielle : le reste attend dans les zones
    g.game.explorationProgression = g.game.explorationProgression || {};
    g.game.explorationProgression[g.PRODUCTION_UNLOCK_FLAGS.quarry] = true;
    run("ProductionManager.ensure();");
    var PPS = g.ProductionPlotsSystem; PPS.ensurePlots("quarry");
    var plots = PPS.getPlots("quarry"); plots[0].state = "open"; plots[0].stock = 300;
    g.game.resources.pierre = 350;
    g.ProductionManager.harvest("quarry");
    ok(g.game.resources.pierre === 500 && Math.floor(PPS.getTotalStock("quarry")) === 150, "E1 : récolte partielle, 150 restent dans les zones");

    // --- E2 : niveaux d'Histoire ---
    g.game.worldsEverReached = { 0: true, 1: true }; g.WorldManager.worldIndex = 1;
    reached(true);
    g.game.village.buildings.training = { level: 6 };
    var ct = VBM.getNextCost("training");
    ok(ct && ct.gold > 0 && !ct.planche && !ct.pierre && !ct.lingot, "E2 : Terrain au plafond de l'acte -> or seulement (" + JSON.stringify(ct) + ")");
    ok(VBM.isNextLevelStoryProvided("training"), "E2 : l'écran sait que les matériaux sont fournis");
    g.game.village.buildings.forge = { level: 2 };
    var cf = VBM.getNextCost("forge");
    ok(cf && cf.verre_trempe === 3 && !cf.pierre && !cf.acier, "E2 : Forge 2 -> 3 : or et Verre trempé, sans pierre ni acier");
    g.game.village.buildings.workshop = { level: 5 };
    ok(!VBM.isNextLevelStoryProvided("workshop") && VBM.getNextCost("workshop").pierre > 0, "E2 : un autre bâtiment garde son coût");
    var F = g.ForgeManager; F.ensure(); g.game.forge.levels.weapon = 0; g.game.forge.levels.armor = 0;
    ok(!F.getCost("weapon").acier && F.getCost("weapon").gold > 0, "E2 : reforge de l'arme 0 -> 1 : sans acier");
    ok(F.getCost("armor").acier > 0, "E2 : l'armure paie son acier");
    g.game.forge.levels.weapon = 4;
    ok(!F.isStoryReforge("weapon", 5), "E2 : au-delà de 4, la reforge de l'arme redevient normale");

    // --- E3 : Bloc taillé ---
    ok(g.WAREHOUSE_RESOURCES.bloc && g.WAREHOUSE_RESOURCES.bloc.sellPrice === 0, "E3 : Bloc taillé, invendable");
    var rb = g.WORKSHOPS_CONFIG.maconnerie.recipes[0];
    ok(rb.inputs[0].resourceId === "pierre" && rb.inputs[0].quantity === 6 && rb.inputs[1].resourceId === "fer" && rb.inputs[1].quantity === 2, "E3 : 6 pierre + 2 fer -> 1 bloc");
    reached(["forest_01"]);
    ok(g.WORKSHOPS_CONFIG.maconnerie.active === false, "E3 : Maçonnerie fermée en Forêt");
    reached(true);
    ok(g.WORKSHOPS_CONFIG.maconnerie.active === true, "E3 : ouverte au Désert");
    g.game.village.buildings.hall = { level: 5 };
    var ch = VBM.getNextCost("hall");
    ok(ch.bloc === 45 && ch.planche === 45, "E3 : Halle au Désert : moitié des planches en blocs (" + ch.planche + " / " + ch.bloc + ")");

    // --- E4 : vivres de sortie ---
    var P = g.ProvisionsManager, hunt = g.HUNT_QUESTS.hq_forest_boar;
    g.game.huntStats = {}; g.game.resources.petite_ration = 0;
    reached(["forest_01"]);
    g.game.huntStats[hunt.id] = 3;
    ok(P.getRequirement("hunt", hunt) === null, "E4 : actes I et II de la Forêt : aucun vivre");
    reached(true);
    g.game.huntStats[hunt.id] = 0;
    ok(P.getRequirement("hunt", hunt) === null, "E4 : première chasse : gratuite");
    g.game.huntStats[hunt.id] = 1;
    var req = P.getRequirement("hunt", hunt);
    ok(req && req.resourceId === "petite_ration", "E4 : chasse refaite en Forêt : 1 petite ration");
    ok(/Vivres/.test(P.check("hunt", hunt) || ""), "E4 : sans ration, le départ est refusé avec la raison");
    g.game.resources.petite_ration = 2;
    ok(P.check("hunt", hunt) === null && P.consume("hunt", hunt) && g.game.resources.petite_ration === 1, "E4 : la ration est prélevée au départ");
    var cite = g.DUNGEONS.filter(function (d) { return d.id === 2; })[0];
    g.game.dungeonTierCleared = {};
    ok(P.getRequirement("dungeon", cite) === null, "E4 : donjon jamais fini : gratuit");
    g.game.dungeonTierCleared[2] = true;
    var sft = g.DungeonManager.isStoryTicketFree; g.DungeonManager.isStoryTicketFree = function () { return false; };
    ok((P.getRequirement("dungeon", cite) || {}).resourceId === "ration", "E4 : Cité refaite : 1 ration moyenne");
    g.DungeonManager.isStoryTicketFree = function () { return true; };
    ok(P.getRequirement("dungeon", cite) === null, "E4 : un ticket d'Histoire reste gratuit");
    g.DungeonManager.isStoryTicketFree = sft;
    var rr = g.WORKSHOPS_CONFIG.cuisine_de_camp.recipes.filter(function (r) { return r.id === "ration"; })[0];
    ok(rr.inputs[0].quantity === 3, "E4 : ration moyenne = 3 viandes séchées + 1 pain");

    // --- E6 : plus de vente, la Taverne seul débouché ---
    g.game.gold = 100; g.game.resources.ble = 100;
    ok(W.sellResource("ble", 50) === 0 && g.game.gold === 100 && g.game.resources.ble === 100, "E6 : l'Entrepôt ne rachète plus rien");
    g.game.village.buildings.workshop = { level: 0 };
    var r0 = g.TavernManager ? g.TavernManager.getRewardFor("fer", 50) : null;
    g.game.village.buildings.workshop = { level: 10 };
    var r10 = g.TavernManager ? g.TavernManager.getRewardFor("fer", 50) : null;
    ok(r0 !== null && r10 > r0, "E6 : l'Atelier de Construction relève les contrats de la Taverne (" + r0 + " -> " + r10 + ")");
    var dh = run("buildWarehouseSheetHTML('fer')");
    ok(dh.indexOf("Vendre") === -1 && dh.indexOf("Taverne") !== -1, "E6 : l'écran de l'Entrepôt renvoie vers la Taverne");
    g.game.genericTutorialsSeen = {};
    ok(run("buildWarehouseHTML()").indexOf("Le tavernier") !== -1, "E6 : mot du tavernier à la première visite");
    run("dismissWarehouseNoSaleNote();");
    ok(run("buildWarehouseHTML()").indexOf("Le tavernier") === -1, "E6 : ...une seule fois");

    // --- v3.330.1 : lignes « Vivres » à l'écran ---
    g.game.huntStats[hunt.id] = 1; g.game.resources.petite_ration = 0;
    ok(/Vivres : 1 Petite ration/.test(P.buildLineHTML("hunt", hunt)) && /is-missing/.test(P.buildLineHTML("hunt", hunt)), "vivres affichés sur la fiche de chasse (manquants)");
    g.game.huntStats[hunt.id] = 0;
    ok(P.buildLineHTML("hunt", hunt) === "", "sortie gratuite : aucune ligne");

    // --- Or de l'Histoire (banc « or par acte ») ---
    ok(g.STORY_REWARDS.desert_11.gold === 2350 && g.STORY_REWARDS.desert_12.gold === 2425 && g.STORY_REWARDS.desert_13.gold === 2475, "étapes 11 à 13 du Désert : +1 000 or chacune (v3.358.0 : essence ×5 incluse)");
  } finally { SQ.isStepReached = reachSave; }
})();

