  ["hf_desert_rare_story", "hf_desert_retaken"].forEach(function (k) { delete stc.reached[k]; });
  var hd = g.buildAchievementsHTML();
  ok(hd.indexOf("???") !== -1, "écran : un caché non trouvé s'affiche « ??? »");
  run("achievementTab = 'collection'; achievementOldOpen = true;");
  game.achievementsClaimed.ach_kills_1 = true;
  ok(g.buildAchievementsHTML().indexOf("Anciens exploits") !== -1, "écran : « Anciens exploits » en bas de Collection");
  run("achievementTab = null; achievementOldOpen = false;");

  // --- Persistance : les quatre points ---
  var saved2 = g.buildSaveData();
