  ok(st.narrative.dialogue.length === 7 && st.narrative.completionDialogue.length === 5 && st.narrative.dialogue[3].who === null, "textes validés : 7 répliques au départ (dont la ligne du narrateur), 5 au trône");
  S.acceptStep("desert");

  var T = g.SCENE_TEMPLATES.remontee_fleuve;
  /* v3.390.0 (chantier P, P-2) : parcours v2 dans le lit asséché, besace de 3 places (H4). */
